/* V2.1.67 — V3 Thai source, editorial English localization; concept studies. */
(function(){
const deep=[{"brand":"VERA LEAF","title":"สร้างภาพลักษณ์สกินแคร์ธรรมชาติให้เป็นระบบเดียวกัน","summary":"พัฒนาภาษาภาพของสกินแคร์หลาย SKU ให้จดจำง่าย สอดคล้องกัน และรองรับการต่อยอดสินค้า","headline":{"th":"ธรรมชาติที่ไม่ได้มีเพียงภาพใบไม้ แต่มีระบบที่ทำให้เลือกสินค้าได้ง่ายขึ้น","en":"Nature is more than a leaf: a system that makes skincare easier to choose."},"timeline":[{"step":"01","heading":{"th":"จุดเริ่มต้นและบริบท","en":"Project Brief"},"body":{"th":"ลองจินตนาการถึงแบรนด์สกินแคร์ที่เริ่มจากเซรั่มหนึ่งขวด แล้วขยายเป็นคลีนเซอร์และครีม เมื่อแต่ละสูตรมีขนาดภาชนะต่างกัน ภาพของแบรนด์เริ่มแตกออกเป็นหลายทิศทาง ทั้งที่สินค้าควรเล่าเรื่องเดียวกัน\n\nแบรนด์สกินแคร์ในโจทย์สมมติต้องการภาพลักษณ์ที่สะท้อนความเรียบง่ายและส่วนผสมจากพืช แต่มีผลิตภัณฑ์หลายประเภท ขวดและกระปุกขนาดต่างกัน จึงต้องมีระบบที่ทำให้ทุกชิ้นอยู่ในครอบครัวเดียวกันโดยยังแยกประเภทได้ชัดเจน\n\nกลุ่มเป้าหมายที่ตั้งไว้ในโจทย์คือคนที่ต้องการจัดกิจวัตรดูแลผิวให้เข้าใจง่าย ไม่จำเป็นต้องรู้ชื่อสารสกัดทุกชนิดก่อนเลือกซื้อ ประสบการณ์เริ่มตั้งแต่ค้นหาสินค้าบนมือถือ เห็นขวดจริง ไปจนถึงหยิบใช้ในห้องน้ำ สิ่งที่แบรนด์ต้องการจึงไม่ใช่ฉลากใหม่เพียงชุดเดียว แต่เป็นระบบที่ทำให้การเปิดตัวสินค้าชิ้นถัดไปไม่ต้องสร้างบุคลิกใหม่ตั้งแต่ต้น","en":"A serum becomes a cleanser and cream range. Different bottle and jar sizes must still feel like one family. The brief is a reusable system that helps people understand their routines, from a phone-sized product image to a bottle in the bathroom."}},{"step":"02","heading":{"th":"Pain Point และเหตุผลที่ต้องเปลี่ยน","en":"Insight"},"body":{"th":"ลูกค้าอาจแยกประเภทผลิตภัณฑ์ได้ยากเมื่อฉลากทุกสูตรคล้ายกัน หรือจำแบรนด์ไม่ได้เมื่อแต่ละสูตรใช้กราฟิกต่างกันมากเกินไป ความท้าทายคือสร้างความเป็นครอบครัวโดยไม่เสียความชัดเจนของข้อมูล\n\nผู้ซื้อควรอ่านชื่อประเภทสินค้าและจุดเด่นได้ก่อนรายละเอียดรอง ภาษาภาพจึงต้องทำหน้าที่ทั้งสร้างอารมณ์และช่วยเลือกสินค้า ไม่ใช้ลวดลายพฤกษศาสตร์จนกลบข้อความสำคัญ\n\nลองวางเซรั่ม คลีนเซอร์ และครีมไว้ด้วยกัน หากชื่อผลิตภัณฑ์เล็กกว่าภาพใบไม้ ผู้ใช้ต้องอ่านนานขึ้นกว่าจะทราบว่าขวดใดใช้ในขั้นตอนใด ในทางกลับกัน ถ้าทุกชิ้นแตกต่างกันเพื่อให้แยกง่าย แบรนด์ก็สูญเสียความต่อเนื่อง โจทย์จึงเป็นการจัดสมดุลระหว่าง Recognition กับ Navigation: ให้จำแบรนด์ได้ก่อน แล้วเข้าใจประเภทสินค้าโดยไม่ต้องพึ่งสีเพียงอย่างเดียว","en":"Balance brand recognition with product navigation. If botanical imagery overwhelms the product name, people struggle to distinguish the steps; if every formula looks different, the brand loses continuity. Use names and hierarchy as well as colour."}},{"step":"03","heading":{"th":"แนวคิดหลักและเหตุผลของอัตลักษณ์","en":"Creative Direction"},"body":{"th":"Botanical Clarity — ความเป็นธรรมชาติที่มีระเบียบและอ่านง่าย ให้ความรู้สึกอ่อนโยนผ่านวัสดุ สี และช่องว่าง ไม่ใช่การกล่าวอ้างคุณสมบัติผลิตภัณฑ์\n\nใบไม้และตัวอักษร Serif เป็นสัญลักษณ์ของความละเอียดอ่อนและความเรียบสงบ ใช้เขียวหม่นเป็นสีหลักเพื่อเชื่อมโยงกลุ่มสินค้า ส่วนชื่อสูตรต้องอยู่ในลำดับที่มองเห็นก่อนข้อความรอง\n\nBotanical Clarity วางตำแหน่งแบรนด์ให้เป็นสกินแคร์ที่ให้ความสำคัญกับความชัดเจนและความประณีต ไม่ใช่การใช้ภาพธรรมชาติเป็นหลักฐานว่าสินค้าปลอดภัยหรือมีประสิทธิภาพกว่า กราฟิกใบไม้ให้ความรู้สึกถึงการเติบโต ส่วนพื้นที่ว่างสร้างจังหวะหยุดสายตา ตัว Serif ใช้กับชื่อแบรนด์เพื่อสร้างน้ำเสียงที่นิ่ง ขณะที่ตัวอ่านง่ายสำหรับชื่อสูตรและข้อมูลรองทำหน้าที่ให้ผู้ใช้ตัดสินใจได้สะดวกขึ้น","en":"Botanical Clarity — a calm, legible identity. Muted greens, airy botanical motifs, serif brand lettering and clear secondary typography express care and precision, not unverified product benefits. Negative space gives essential information room to breathe."}},{"step":"04","heading":{"th":"Pattern, Mascot และระบบการใช้งาน","en":"Design Development"},"body":{"th":"พัฒนาเส้นใบและกิ่งเป็น Botanical Pattern แบบโปร่ง ใช้ความหนาแน่นและการครอปที่ต่างกันตามพื้นที่ แต่รักษาทิศทางและน้ำหนักเส้นเดียวกัน บนกล่องใช้ลายขยายได้ ขวดเล็กใช้เพียงบางส่วน เพื่อไม่ให้บดบังข้อมูล\n\nไม่จำเป็นต้องมี Mascot เพราะบทบาทหลักคือสื่อสารความชัดเจนของสูตรและภาพลักษณ์สงบ ใช้ภาพพฤกษศาสตร์เป็น Brand Asset แทน\n\nจัดระบบขวดหยด ขวดปั๊ม กระปุก และกล่องให้ใช้กริดชื่อแบรนด์และชื่อผลิตภัณฑ์ร่วมกัน แยกสูตรด้วยชื่อและสีรอง ไม่พึ่งสีเพียงอย่างเดียว\n\nกติกาของระบบภาพคือส่วนที่คงที่ ได้แก่ ตำแหน่งชื่อแบรนด์ สัดส่วนพื้นที่ว่าง และลักษณะเส้นใบ ส่วนที่เปลี่ยนได้คือชื่อสินค้า สีรอง และการครอปภาพพฤกษศาสตร์ ลองใช้ลายใบไม้เต็มขอบกล่อง แต่ลดเหลือเพียงกิ่งเล็กบนขวดหยด เพื่อให้ภาพยังเชื่อมโยงกันโดยไม่เบียดข้อมูล พื้นที่คำอธิบายวิธีใช้ควรแยกจากพื้นที่ตกแต่ง และไม่ใส่ตัวละครเพราะการสื่อสารในหมวดนี้เน้นกิจวัตรและข้อมูลที่น่าเชื่อถือมากกว่าความบันเทิง","en":"Lock brand placement, whitespace proportions and botanical stroke style; vary product name, accent colour and motif crop. Extend the system from dropper bottles to pumps, jars and cartons. A mascot is unnecessary: botanical assets support the quieter information-led character."}},{"step":"05","heading":{"th":"จากแนวคิดสู่การผลิต","en":"Production Strategy"},"body":{"th":"เสนอฉลาก PP สีขาวหรือฟิล์มตามพื้นผิวภาชนะ พิมพ์ CMYK และเคลือบผิวตามความเหมาะสม ทดสอบการยึดเกาะบนขวดจริง ความทนต่อความชื้นและคราบน้ำมัน ตรวจ seam และตำแหน่งฉลากก่อนขึ้นต้นแบบ\n\nภาพลายใบไม้เต็มพื้นที่อาจทำให้ดูเป็นธรรมชาติขึ้นแต่ลดความอ่านง่าย จึงเลือกพื้นที่ว่างมากกว่า พร้อมทดสอบฉลากทนชื้นกับภาชนะจริง\n\nขวดทรงกระบอกและกระปุกเตี้ยต้องใช้พื้นที่ฉลากคนละสัดส่วน จึงควรสร้างแม่แบบตามขนาดภาชนะจริง แทนการย่อ Artwork เดียวทั้งชิ้น พื้นฉลากขาวทึบอาจช่วยให้สีคงที่บนแก้วชา ขณะที่ฟิล์มใสให้เห็นตัวภาชนะแต่ต้องควบคุมพื้นหลังและหมึกขาว หากเลือกผิวด้านให้พิจารณารอยเช็ดและคราบผลิตภัณฑ์ร่วมด้วย ก่อนสรุปให้เทียบตัวอย่างบนขวดจริงและต้นทุนของแต่ละทางเลือก","en":"Build dielines for actual containers rather than scaling a single file. Compare opaque white PP with clear film and selective white ink on amber glass; assess matte surface resistance to oils and wiping. Trial adhesion and seams and compare costs before fixing specifications."}},{"step":"06","heading":{"th":"การทดสอบและตรวจสอบ","en":"Quality Control"},"body":{"th":"ตรวจความอ่านง่ายบนภาชนะจริง การตรงกันของสีระหว่างกล่องและฉลาก ขนาดข้อมูลบังคับและข้อมูลส่วนประกอบที่เจ้าของสินค้ายืนยัน รวมถึงความทนต่อการเช็ดและการขนส่ง\n\nให้ผู้ทดสอบแยกชนิดสินค้าและค้นหาชื่อแบรนด์จากภาพขนาดเล็ก เปรียบเทียบฉลากเรียบกับฉลากลายหนาแน่น ตรวจการยึดเกาะและคราบน้ำมันบนตัวอย่าง\n\nแผนทดสอบแบ่งเป็นสองมิติ: การสื่อสารและความพร้อมผลิต ให้กลุ่มตัวอย่างค้นหาคลีนเซอร์จากภาพรวม SKU และระบุขั้นตอนใช้งานจากฉลาก โดยบันทึกความสับสนและเวลาที่ใช้ จากนั้นตรวจปรู๊ฟสีบนวัสดุจริง การติดฉลากบริเวณโค้ง และความอ่านง่ายของข้อมูลที่เจ้าของผลิตภัณฑ์ตรวจรับรองแล้ว เก็บข้อสังเกตแยกตาม SKU เพื่อแก้ระบบหลัก ไม่แก้เฉพาะขวดที่พบปัญหา","en":"Test recognition and product selection with a small-image SKU lineup, recording confusion and search time. Review proofs in consistent light, apply samples to curved containers and check approved ingredient and required copy, wiping, oil exposure and transport."}},{"step":"07","heading":{"th":"คุณค่าที่คาดหวัง","en":"Concept Outcome"},"body":{"th":"ผลลัพธ์ที่ออกแบบไว้คือระบบภาพลักษณ์ที่ขยาย SKU ได้โดยไม่ต้องออกแบบใหม่ทั้งหมด และทำให้สินค้าแต่ละประเภทแยกกันได้บนชั้นวาง ยังไม่มีการผลิตหรือทดสอบกับผู้บริโภคจริง\n\nเมื่อจะเพิ่มสินค้าใหม่ เช่น มาสก์หรือโลชั่น ทีมสามารถเริ่มจากกริด สีรอง และกติกาการใช้ลายที่มีอยู่ แทนการตั้งโจทย์ภาพลักษณ์ใหม่ทั้งหมด สิ่งที่จะส่งมอบในแนวคิดนี้จึงเป็นทั้งแม่แบบและคู่มือการตัดสินใจ คุณค่าที่ควรวัดเมื่อทดสอบจริงคือความถูกต้องในการเลือกประเภทสินค้า ความสม่ำเสมอของภาพรวม และเวลาที่ใช้พัฒนา SKU ใหม่ ไม่ใช่ยอดขายที่ยังไม่มีข้อมูล","en":"A master grid, accent colours and motif rules should allow masks or lotions to join the range without redesigning its identity. Evaluate identification accuracy, consistency and new-SKU development time in a future trial; no sales or consumer results are claimed."}}],"storytelling":{"opening":"ลองจินตนาการถึงแบรนด์สกินแคร์ที่เริ่มจากเซรั่มหนึ่งขวด แล้วขยายเป็นคลีนเซอร์และครีม เมื่อแต่ละสูตรมีขนาดภาชนะต่างกัน ภาพของแบรนด์เริ่มแตกออกเป็นหลายทิศทาง ทั้งที่สินค้าควรเล่าเรื่องเดียวกัน","pain_point":"ลูกค้าอาจแยกประเภทผลิตภัณฑ์ได้ยากเมื่อฉลากทุกสูตรคล้ายกัน หรือจำแบรนด์ไม่ได้เมื่อแต่ละสูตรใช้กราฟิกต่างกันมากเกินไป ความท้าทายคือสร้างความเป็นครอบครัวโดยไม่เสียความชัดเจนของข้อมูล","big_idea":"Botanical Clarity — ความเป็นธรรมชาติที่มีระเบียบและอ่านง่าย ให้ความรู้สึกอ่อนโยนผ่านวัสดุ สี และช่องว่าง ไม่ใช่การกล่าวอ้างคุณสมบัติผลิตภัณฑ์","logo_rationale":"ใบไม้และตัวอักษร Serif เป็นสัญลักษณ์ของความละเอียดอ่อนและความเรียบสงบ ใช้เขียวหม่นเป็นสีหลักเพื่อเชื่อมโยงกลุ่มสินค้า ส่วนชื่อสูตรต้องอยู่ในลำดับที่มองเห็นก่อนข้อความรอง","pattern_rationale":"พัฒนาเส้นใบและกิ่งเป็น Botanical Pattern แบบโปร่ง ใช้ความหนาแน่นและการครอปที่ต่างกันตามพื้นที่ แต่รักษาทิศทางและน้ำหนักเส้นเดียวกัน บนกล่องใช้ลายขยายได้ ขวดเล็กใช้เพียงบางส่วน เพื่อไม่ให้บดบังข้อมูล","mascot_rationale":"ไม่จำเป็นต้องมี Mascot เพราะบทบาทหลักคือสื่อสารความชัดเจนของสูตรและภาพลักษณ์สงบ ใช้ภาพพฤกษศาสตร์เป็น Brand Asset แทน","application_system":"จัดระบบขวดหยด ขวดปั๊ม กระปุก และกล่องให้ใช้กริดชื่อแบรนด์และชื่อผลิตภัณฑ์ร่วมกัน แยกสูตรด้วยชื่อและสีรอง ไม่พึ่งสีเพียงอย่างเดียว","trade_off":"ภาพลายใบไม้เต็มพื้นที่อาจทำให้ดูเป็นธรรมชาติขึ้นแต่ลดความอ่านง่าย จึงเลือกพื้นที่ว่างมากกว่า พร้อมทดสอบฉลากทนชื้นกับภาชนะจริง","validation_plan":"ให้ผู้ทดสอบแยกชนิดสินค้าและค้นหาชื่อแบรนด์จากภาพขนาดเล็ก เปรียบเทียบฉลากเรียบกับฉลากลายหนาแน่น ตรวจการยึดเกาะและคราบน้ำมันบนตัวอย่าง","visual_asset_brief":["Brand mark และ botanical motif","Pattern tile และตัวอย่างครอป","SKU family บนขวดสามทรง","Macro ฉลากและผิววัสดุ","ภาพรวมบรรจุภัณฑ์และกล่อง"]},"deliverables":["Logo & visual identity","Master label system","Packaging artwork direction","Material & prototype checklist"],"assetNotes":"โลโก้เวกเตอร์ต้นแบบสร้างแยกจากภาพจำลอง อาจมีรายละเอียดไม่ตรงกับโลโก้ใน Mockup ทุกจุด; ภาพ hero และ card มาจากภาพเดียวกัน ไม่ใช่ภาพถ่ายจริง; ชื่อแบรนด์ยังไม่ได้ตรวจสอบสิทธิ์เครื่องหมายการค้า","featured":true},{"brand":"ZESTORA","title":"ออกแบบฉลากเครื่องดื่มให้โดดเด่นในตู้แช่","summary":"ฉลากสีสดที่มองเห็นได้ชัดในสภาพแช่เย็น พร้อมวางแนวทางวัสดุให้เหมาะกับหยดน้ำและการจับสัมผัส","headline":{"th":"ชนะพื้นที่สายตาในตู้แช่ โดยไม่ทำให้ข้อมูลรสชาติหายไป","en":"Stand out in the chiller without losing the flavour information."},"timeline":[{"step":"01","heading":{"th":"จุดเริ่มต้นและบริบท","en":"Project Brief"},"body":{"th":"ในตู้แช่ที่มีขวดเครื่องดื่มเรียงแน่น ผู้ซื้ออาจเห็นสินค้าผ่านแสงสะท้อนและหยดน้ำเพียงชั่วครู่ ZESTORA จึงต้องทำให้ชื่อและรสชาติสื่อสารได้แม้ในสภาพที่ไม่เหมือนภาพบนจอ\n\nโจทย์สมมติของเครื่องดื่มรสส้มพร้อมดื่มคือการแข่งขันบนชั้นแช่เย็นที่มีสินค้าจำนวนมาก ฉลากต้องอ่านได้ในระยะสั้นและยังดูดีเมื่อมีหยดน้ำเกาะภายนอก\n\nสถานการณ์ตั้งต้นคือเครื่องดื่มผลไม้พร้อมดื่มที่ต้องแข่งขันในตู้แช่และภาพสินค้าออนไลน์พร้อมกัน ผู้ซื้ออาจมองผ่านประตูกระจกในเวลาสั้น ๆ เห็นเพียงด้านหน้าขวดหรือขอบฉลากจากมุมเฉียง แบรนด์จึงต้องคิดตั้งแต่จุดที่ผู้ซื้อยังไม่หยิบสินค้า ไม่ใช่ประเมินฉลากจากไฟล์แบนบนจอเพียงอย่างเดียว","en":"A hypothetical ready-to-drink fruit range needs to communicate through a glass chiller door and online thumbnails. Plan for a brief glance at a front or angled bottle, not just flat artwork."}},{"step":"02","heading":{"th":"Pain Point และเหตุผลที่ต้องเปลี่ยน","en":"Insight"},"body":{"th":"ฉลากที่พึ่งภาพผลไม้เพียงอย่างเดียวอาจคล้ายคู่แข่ง ส่วนการเพิ่มข้อความหรือกราฟิกจำนวนมากทำให้ชื่อแบรนด์ไม่เด่น เมื่อเพิ่มรสชาติใหม่ ความแตกต่างระหว่าง SKU ต้องไม่ทำลายเอกภาพ\n\nการมองเห็นชื่อแบรนด์และรสชาติอย่างรวดเร็วสำคัญกว่าการเพิ่มองค์ประกอบจำนวนมาก สีและคอนทราสต์จึงต้องทำงานร่วมกับรูปทรงขวดจริงและแสงจากตู้แช่\n\nสีส้มของน้ำและภาพส้มบนฉลากอาจทำให้สินค้าเด่นในภาพเดี่ยว แต่เมื่อวางติดกับเครื่องดื่มสีส้มอื่น ๆ จุดจดจำอาจหายไป หากเพิ่มรสใหม่โดยเปลี่ยนทั้งสีพื้นและรูปแบบตัวอักษร ผู้ซื้ออาจไม่เชื่อมโยงว่าเป็นแบรนด์เดียวกัน ความท้าทายจึงมีทั้งการถูกมองเห็น การอ่านชื่อ และการแยกรส โดยสามอย่างนี้ต้องเกิดร่วมกัน","en":"Orange liquid and fruit imagery can disappear among similar drinks. Keep a recognisable brand anchor while distinguishing flavours, so visibility, name recognition and flavour selection work together."}},{"step":"03","heading":{"th":"แนวคิดหลักและเหตุผลของอัตลักษณ์","en":"Creative Direction"},"body":{"th":"Fresh Impact — สร้างพลังจากทิศทางเฉียง สีตัดกัน และจังหวะที่ชัดเจน ให้ความสดชื่นผ่านภาพโดยไม่ต้องอ้างสรรพคุณ\n\nwordmark หนาเอียงสื่อการเคลื่อนไหว สีเขียวเข้มเป็นฐานคงที่ช่วยให้แบรนด์แยกจากสีส้มของเครื่องดื่มและภาพผลไม้\n\nFresh Impact แปลงความรู้สึกสดชื่นเป็นทิศทางการเคลื่อนที่ของกราฟิก แทนการใส่ภาพน้ำกระเซ็นจำนวนมาก Wordmark ตัวหนาเอียงอยู่บนฐานสีเขียวเข้มเพื่อสร้างความต่างกับน้ำสีส้ม ความเอียงของตัวอักษรเป็นต้นกำเนิดของแถบเฉียงที่ใช้ซ้ำในระบบ ไม่ใช่เพียงเอฟเฟกต์ตกแต่ง ตัวอักษรชื่อรสเลือกน้ำหนักที่อ่านง่ายแม้ฉลากถูกมองผ่านแสงสะท้อน","en":"Fresh Impact — bold italic lettering on a dark-green anchor creates contrast with orange liquid. Its angle informs the dynamic graphics; clear flavour typography remains legible through reflections. Visual freshness is not a health claim."}},{"step":"04","heading":{"th":"Pattern, Mascot และระบบการใช้งาน","en":"Design Development"},"body":{"th":"ใช้แถบเฉียงและชิ้นส่วนรูปทรงผลไม้เป็น Dynamic Pattern ต่อจากมุมของ wordmark ปรับสีผลไม้ตามรสชาติ แต่เก็บทิศทางเดิมเพื่อให้จำกลุ่มสินค้าได้\n\nไม่เลือก Mascot เพราะพื้นที่ด้านหน้าขวดมีจำกัด และชื่อแบรนด์กับรสชาติมีความสำคัญกว่า ตัวละครอาจแย่งสายตาจากข้อมูลหลัก\n\nขยายระบบจากฉลากส้มไปยังรสชาติสมมติอื่นด้วยกริดและแถบสีเดียวกัน ใช้แถบเฉียงในป้ายตู้แช่และสื่อส่งเสริมการขาย\n\nให้แถบเขียวและตำแหน่งชื่อ ZESTORA เป็นองค์ประกอบคงที่ ส่วนสีผลไม้ ชื่อรส และภาพวัตถุดิบเป็นองค์ประกอบเปลี่ยนได้ เมื่อทดลองรสสมมติใหม่ เช่น มะม่วงหรือเบอร์รี สามารถเปลี่ยนสีรองและภาพผลไม้โดยไม่ทำลายทิศทางเฉียงเดิม ลายกราฟิกที่ขยายบนป้ายตู้แช่จึงยังเชื่อมโยงกับฉลากบนขวดได้ ส่วน Mascot ไม่ได้มีบทบาทจำเป็น เพราะต้องสงวนพื้นที่ให้ชื่อและรสเป็นหลัก","en":"Keep the green band, wordmark placement and diagonal direction fixed; vary fruit colours, names and imagery. Extend the motif to promotional chiller signage. No mascot is needed because the brand and flavour must take priority."}},{"step":"05","heading":{"th":"จากแนวคิดสู่การผลิต","en":"Production Strategy"},"body":{"th":"เสนอฟิล์ม BOPP/PP หรือระบบฉลากที่เหมาะกับเครื่องติดของผู้ผลิต เลือกกาวหลังประเมินขวดและสภาพติดฉลากจริง พิจารณาหมึกขาวรองพื้นเมื่อใช้ฟิล์มใส และทำ wet/cold test ก่อนอนุมัติ\n\nฟิล์มใสทำให้เห็นน้ำเครื่องดื่มได้ แต่สีกราฟิกอาจเปลี่ยนตามพื้นหลัง จึงต้องเปรียบเทียบหมึกขาวรองพื้นและวัสดุทึบพร้อมทดสอบการติดฉลาก\n\nการเลือกฉลากควรเริ่มจากชนิดขวด รูปร่าง และวิธีติดฉลากจริง ฟิล์มทึบอาจช่วยให้สีกราฟิกมีฐานคงที่ ส่วนฟิล์มใสพร้อมหมึกขาวเฉพาะบริเวณสามารถเปิดให้เห็นเครื่องดื่ม แต่เพิ่มเงื่อนไขด้านการควบคุมสีและการซ้อนหมึก ทดลองตำแหน่งรอยต่อบนพื้นที่ที่ไม่ตัดชื่อรส และขอข้อมูลจากผู้ผลิตเรื่องกาว สภาพแช่เย็น และขนาดฉลากก่อนสรุปสเปก","en":"Compare opaque stock and clear film with selective white ink on the actual bottle. Confirm the adhesive, application temperature and chiller exposure; position the seam away from the flavour name. Assess colour shifts through the liquid and condensation before approval."}},{"step":"06","heading":{"th":"การทดสอบและตรวจสอบ","en":"Quality Control"},"body":{"th":"ตรวจการลอกขอบหลังแช่เย็น การคงสภาพของหมึก ความบิดเบี้ยวของกราฟิกบริเวณส่วนโค้งและความอ่านง่ายของข้อมูลสินค้า ทดสอบบาร์โค้ดบนขวดจริง\n\nเปรียบเทียบการอ่านชื่อและรสจากภาพจำลองตู้แช่ที่ระยะต่างกัน ทดสอบฉลากเมื่อเย็นและมีหยดน้ำ รวมถึงรอยต่อบนขวดจริง\n\nจัดการทดสอบด้วยภาพจำลองชั้นวางหลายแบรนด์ แล้วให้ผู้ทดสอบระบุชื่อและรสจากมุมมองปกติและมุมเฉียง บันทึกว่าข้อมูลใดถูกอ่านผิดหรือมองข้าม จากนั้นตรวจตัวอย่างพิมพ์บนขวดที่ผ่านสภาพเย็นและมีหยดน้ำ ดูการยกขอบ รอยย่น และความชัดของกราฟิก เกณฑ์ยอมรับควรตกลงกับผู้ผลิตตามวัสดุและสภาพใช้งานจริง","en":"Test recognition and flavour reading in a simulated multi-brand shelf at frontal and oblique angles. Review printed bottles after representative chilling and condensation, checking wrinkles, edge lift and readability against agreed criteria."}},{"step":"07","heading":{"th":"คุณค่าที่คาดหวัง","en":"Concept Outcome"},"body":{"th":"แนวทางต้นแบบทำให้แบรนด์มีโครงฉลากที่รองรับการเพิ่มรสชาติและมีแผนทดสอบสภาพแช่เย็นชัดเจน ยังไม่มีผลการขายหรือผลทดสอบวัสดุจริง\n\nหากแนวคิดผ่านการทดสอบ แบรนด์จะมีระบบฉลากที่นำไปใช้ได้กับรสใหม่ ป้ายส่งเสริมการขาย และภาพสินค้าออนไลน์โดยยังรักษาเอกลักษณ์เดิม เป้าหมายไม่ใช่การรับประกันว่าจะขายดีขึ้น แต่คือการเพิ่มความชัดเจนของชื่อและรสชาติในบริบทที่ผู้บริโภคพบสินค้า และลดความจำเป็นในการออกแบบระบบใหม่ทุกครั้งที่มี SKU เพิ่ม","en":"If validated, the system can extend to new flavours, online imagery and promotions without rebuilding the visual identity. The intended measures concern recognition and clarity, not a promise of increased sales."}}],"storytelling":{"opening":"ในตู้แช่ที่มีขวดเครื่องดื่มเรียงแน่น ผู้ซื้ออาจเห็นสินค้าผ่านแสงสะท้อนและหยดน้ำเพียงชั่วครู่ ZESTORA จึงต้องทำให้ชื่อและรสชาติสื่อสารได้แม้ในสภาพที่ไม่เหมือนภาพบนจอ","pain_point":"ฉลากที่พึ่งภาพผลไม้เพียงอย่างเดียวอาจคล้ายคู่แข่ง ส่วนการเพิ่มข้อความหรือกราฟิกจำนวนมากทำให้ชื่อแบรนด์ไม่เด่น เมื่อเพิ่มรสชาติใหม่ ความแตกต่างระหว่าง SKU ต้องไม่ทำลายเอกภาพ","big_idea":"Fresh Impact — สร้างพลังจากทิศทางเฉียง สีตัดกัน และจังหวะที่ชัดเจน ให้ความสดชื่นผ่านภาพโดยไม่ต้องอ้างสรรพคุณ","logo_rationale":"wordmark หนาเอียงสื่อการเคลื่อนไหว สีเขียวเข้มเป็นฐานคงที่ช่วยให้แบรนด์แยกจากสีส้มของเครื่องดื่มและภาพผลไม้","pattern_rationale":"ใช้แถบเฉียงและชิ้นส่วนรูปทรงผลไม้เป็น Dynamic Pattern ต่อจากมุมของ wordmark ปรับสีผลไม้ตามรสชาติ แต่เก็บทิศทางเดิมเพื่อให้จำกลุ่มสินค้าได้","mascot_rationale":"ไม่เลือก Mascot เพราะพื้นที่ด้านหน้าขวดมีจำกัด และชื่อแบรนด์กับรสชาติมีความสำคัญกว่า ตัวละครอาจแย่งสายตาจากข้อมูลหลัก","application_system":"ขยายระบบจากฉลากส้มไปยังรสชาติสมมติอื่นด้วยกริดและแถบสีเดียวกัน ใช้แถบเฉียงในป้ายตู้แช่และสื่อส่งเสริมการขาย","trade_off":"ฟิล์มใสทำให้เห็นน้ำเครื่องดื่มได้ แต่สีกราฟิกอาจเปลี่ยนตามพื้นหลัง จึงต้องเปรียบเทียบหมึกขาวรองพื้นและวัสดุทึบพร้อมทดสอบการติดฉลาก","validation_plan":"เปรียบเทียบการอ่านชื่อและรสจากภาพจำลองตู้แช่ที่ระยะต่างกัน ทดสอบฉลากเมื่อเย็นและมีหยดน้ำ รวมถึงรอยต่อบนขวดจริง","visual_asset_brief":["Logo และ diagonal graphic","Flavor color system","ภาพขวดในตู้แช่","Macro หยดน้ำและขอบฉลาก","ตัวอย่าง front/back label"]},"deliverables":["Beverage label concept","Flavor hierarchy","Print artwork specification","Cold-condition test plan"],"assetNotes":"โลโก้เวกเตอร์ต้นแบบสร้างแยกจากภาพจำลอง อาจมีรายละเอียดไม่ตรงกับโลโก้ใน Mockup ทุกจุด; ภาพ hero และ card มาจากภาพเดียวกัน ไม่ใช่ภาพถ่ายจริง; ชื่อแบรนด์ยังไม่ได้ตรวจสอบสิทธิ์เครื่องหมายการค้า","featured":true},{"brand":"PAW PARADE","title":"ต่อยอดคาแรกเตอร์เป็นสติกเกอร์สะสมและของพรีเมียม","summary":"ออกแบบระบบคาแรกเตอร์ที่มีบุคลิกแตกต่างกัน แต่คงภาษาภาพเดียวกันสำหรับแคมเปญและสินค้า","headline":{"th":"จากของแจกชั่วคราว สู่โลกของเพื่อนตัวเล็กที่คนอยากสะสม","en":"From a one-off giveaway to a world of small friends worth collecting."},"timeline":[{"step":"01","heading":{"th":"จุดเริ่มต้นและบริบท","en":"Project Brief"},"body":{"th":"แบรนด์ Pet Lifestyle สมมติใช้ของแจกและสติกเกอร์ในแคมเปญ แต่เมื่อแคมเปญจบ ภาพกราฟิกแต่ละชุดก็ถูกเก็บไป การสร้างภาพใหม่ทุกครั้งทำให้การจดจำไม่ต่อเนื่อง PAW PARADE จึงเริ่มจากการคิดว่าจะสร้างสินทรัพย์ของแบรนด์ที่มีชีวิตยาวกว่าแคมเปญได้อย่างไร\n\nแบรนด์ Pet Lifestyle ในโจทย์สมมติต้องการชุดคาแรกเตอร์ที่นำไปใช้ในแคมเปญได้หลายครั้ง ตั้งแต่สติกเกอร์แจกถึงสินค้าสะสม โดยไม่ต้องสร้างภาษาภาพใหม่ทุกครั้ง\n\nโจทย์ของ PAW PARADE มองไปไกลกว่าการขายสติกเกอร์ กลุ่มเป้าหมายสมมติคือคนรักสัตว์และผู้ที่ชอบของสะสมขนาดเล็ก ซึ่งอาจเลือกตัวละครจากอารมณ์ที่ตรงกับตัวเองมากกว่าฟังก์ชันสินค้าเพียงอย่างเดียว แบรนด์จึงมีโอกาสสร้างเรื่องเล่าที่ผู้ซื้ออยากกลับมาติดตาม แม้แคมเปญแรกจะจบแล้ว","en":"PAW PARADE explores a collectible character brand for animal lovers. People may choose a character that reflects their mood rather than a product function. The goal is a world that remains interesting after the first campaign."}},{"step":"02","heading":{"th":"Pain Point และเหตุผลที่ต้องเปลี่ยน","en":"Insight"},"body":{"th":"หากแบรนด์สื่อสารด้วยรูปสัตว์น่ารักทั่วไปเพียงอย่างเดียว ยากที่จะสร้างความแตกต่างและบุคลิกเฉพาะ การวาดตัวละครใหม่โดยไม่มีระบบยังทำให้สัดส่วน สี และน้ำหนักเส้นไม่สม่ำเสมอ\n\nเสน่ห์ของชุดสะสมมาจากความแตกต่างของท่าทางและอารมณ์ ภายใต้กติกาภาพที่เหมือนกัน การออกแบบจึงต้องคิดทั้งตัวละครและข้อจำกัดของขนาดงานพิมพ์ตั้งแต่ต้น\n\nรูปสัตว์น่ารักทั่วไปสามารถดึงดูดสายตาได้ แต่หากไม่มีลักษณะที่จดจำซ้ำ ภาพหนึ่งชิ้นอาจไม่เชื่อมโยงกับอีกชิ้น การจ้างวาดใหม่ทุกแคมเปญยังเสี่ยงให้บุคลิก เส้น และโทนสีเปลี่ยนไป ความท้าทายไม่ใช่การวาดตัวละครให้ได้จำนวนมากที่สุด แต่สร้างแกนเรื่องราวที่อนุญาตให้เปลี่ยนท่าทางได้โดยยังรู้ว่าเป็นเพื่อนตัวเดิม","en":"Cute animals alone are not a consistent identity. Repeated commissions can change proportions, strokes and personality; establish recognisable features so a new pose still feels like the same friend."}},{"step":"03","heading":{"th":"แนวคิดหลักและเหตุผลของอัตลักษณ์","en":"Creative Direction"},"body":{"th":"Little Friends, Big Personality — สร้างโลกที่ผู้คนเลือกเพื่อนตัวเล็กซึ่งสะท้อนบุคลิกของตนได้ ให้ความสนุกเกิดจากเรื่องราว ไม่ใช่เพียงจำนวนตัวละคร\n\nwordmark กลมมนและรอยเท้าสัตว์เป็นลายเซ็นที่ใช้งานได้แม้ไม่มีตัวละคร สีส้มให้ความสนุกและทำหน้าที่เป็นจุดยึดร่วมในคอลเลกชัน\n\nLittle Friends, Big Personality ตั้งแนวคิดให้แต่ละตัวละครเป็นตัวแทนความรู้สึกที่แตกต่างกัน คอร์กี้ชวนออกไปลองสิ่งใหม่ แมวขี้สงสัยชวนสำรวจ และแพนด้าชวนพักจากความวุ่นวาย ทั้งสามเป็นบุคลิกที่เสนอขึ้นสำหรับจักรวาลสมมติ ไม่ใช่ประวัติที่เกิดขึ้นจริง โลโก้ทรงมนกับรอยเท้าทำหน้าที่เป็นเครื่องหมายของโลกใบนี้ แม้บนชิ้นงานที่ไม่มีตัวละครปรากฏ สีส้มเป็นจุดยึดร่วม ส่วนสีเฉพาะตัวช่วยแยกเพื่อนแต่ละตัว","en":"Little Friends, Big Personality — a lively corgi, curious cat and calm panda offer distinct proposed personalities. Rounded type and the paw mark identify the world without characters; orange provides a shared anchor while individual palettes distinguish them."}},{"step":"04","heading":{"th":"Pattern, Mascot และระบบการใช้งาน","en":"Design Development"},"body":{"th":"นำรอยเท้า กระดูก หัวใจ และดาวมาสร้าง Secondary Pattern กำหนดระยะห่างและขนาดให้มีจังหวะ ใช้บนแผ่นรอง ถุง และสื่อออนไลน์โดยไม่ทำให้ตัวละครหลักกลืนไปกับพื้นหลัง\n\nMascot เป็นแกนของโจทย์: กำหนดคอร์กี้เป็นตัวหลักที่ร่าเริง แมวเป็นเพื่อนขี้สงสัย และแพนด้าเป็นเพื่อนใจเย็น พัฒนาสัดส่วนใบหน้า ท่าทาง และ Expression Sheet เพื่อสร้างเรื่องใหม่โดยยังจำได้ว่าเป็นตัวเดิม ตัวละครสมทบไม่จำเป็นต้องปรากฏทุกชิ้น\n\nทำชุดสติกเกอร์เริ่มต้นและต่อยอดเป็น Seasonal Collection แผ่นรองมีโครงคงที่ เปลี่ยนท่าทางและองค์ประกอบประกอบตามธีม ใช้คาแรกเตอร์สื่อสารความรู้สึกใน Social Content\n\nการทำ Mascot ต้องเริ่มจาก Character Bible: โครงหน้า สัดส่วนตา รูปหู ลักษณะเส้น สีหลัก จุดเด่นที่ห้ามเปลี่ยน และชุดสีหน้า จากนั้นจึงเสนอท่าดีใจ ง่วง หรือสงสัย โดยท่าต่าง ๆ ต้องสื่อบุคลิกเดียวกัน ลายรอยเท้า ดาว กระดูก และหัวใจทำหน้าที่เป็นฉากประกอบ ไม่ใช่พระเอกของภาพ ใช้ Pattern ขนาดเล็กบนแผ่นรองหรือถุง แต่เว้นพื้นที่รอบคาแรกเตอร์หลักให้เห็นชัด ระบบนี้รองรับการสร้างธีมตามฤดูกาลโดยไม่ต้องสร้าง Mascot ใหม่ทุกครั้ง","en":"Create a character bible with face proportions, eyes, ears, colours, fixed features and an expression sheet. Use paw, bone, heart and star motifs on backing cards and bags without competing with the main character. Develop seasonal themes within the same rules."}},{"step":"05","heading":{"th":"จากแนวคิดสู่การผลิต","en":"Production Strategy"},"body":{"th":"พิจารณาสติกเกอร์ PP หรือกระดาษตามอายุใช้งาน กำหนดเส้นคัตแยกจากกราฟิก ระยะ bleed และระยะปลอดภัยตามเครื่องจริง เลือกเคลือบเพื่อป้องกันการถูถ้าจำเป็น\n\nเส้นบางหรือส่วนยื่นมากอาจไดคัทยาก จึงทำเวอร์ชัน simplified สำหรับขนาดเล็ก แยกเส้นคัตและกราฟิกตามข้อกำหนดของผู้ผลิตจริง\n\nสำหรับสติกเกอร์ไดคัท รูปทรงตัวละครต้องคิดถึงช่องแคบ ปลายแหลม และส่วนที่ยื่นออกจากลำตัว ทำเวอร์ชันรายละเอียดเต็มสำหรับภาพใหญ่และเวอร์ชันลดทอนสำหรับงานขนาดเล็ก เส้นขอบขาวอาจช่วยแยกตัวละครออกจากพื้นผิวที่ติด แต่ต้องกำหนดร่วมกับระยะคลาดเคลื่อนของเครื่องตัด แยกไฟล์กราฟิกกับเส้นไดคัท และให้ผู้ผลิตยืนยันวิธีตัดก่อนทำแม่แบบจำนวนมาก","en":"Check narrow gaps, sharp corners and small projections before die cutting. Make full-detail and simplified versions for different sizes; set the white border against cutter tolerances and separate vector cut paths from graphics to match the producer’s workflow."}},{"step":"06","heading":{"th":"การทดสอบและตรวจสอบ","en":"Quality Control"},"body":{"th":"ตรวจเส้นคัตไม่ตัดเข้าองค์ประกอบหลัก ขนาดชิ้นเล็กไม่หลุดหรือฉีกง่าย สีของตัวละครตรงกันระหว่างล็อต และทดสอบการลอกจากแผ่นรอง\n\nทดสอบการจำตัวละครเมื่อเปลี่ยนท่าทาง การอ่านอารมณ์ที่ขนาดเล็ก ความทนต่อการลอกและตัด รวมถึงความสอดคล้องของสีในแต่ละชุด\n\nทดสอบโดยสลับท่าทางและขนาดภาพ แล้วดูว่าผู้ทดสอบยังระบุได้ว่าเป็นตัวละครใดและเข้าใจอารมณ์ที่ต้องการหรือไม่ ตรวจตัวอย่างสติกเกอร์จริงสำหรับเส้นขอบแคบ สีหน้าเล็ก การลอกออกจากแผ่นรอง และความต่อเนื่องของสีในคอลเลกชัน หากเส้นบางส่วนหายหลังพิมพ์ ให้ปรับกติกาเวอร์ชันขนาดเล็กแทนการบังคับให้ทุกขนาดใช้ภาพเดียวกัน","en":"Trial recognition across poses and sizes, then inspect printed samples for facial details, registration, edge clearance, peeling and colour consistency. Adjust the small-size rules rather than forcing the same drawing into every size."}},{"step":"07","heading":{"th":"คุณค่าที่คาดหวัง","en":"Concept Outcome"},"body":{"th":"ต้นแบบแสดงการนำระบบคาแรกเตอร์ไปต่อยอดเป็นหลายชิ้นงานอย่างสอดคล้องกัน พร้อมข้อกำหนดเพื่อเตรียมผลิต ยังไม่ได้จัดทำคอลเลกชันจำหน่ายจริง\n\nแนวคิดนี้สร้างฐานสำหรับคอลเลกชันที่เติบโตจากสติกเกอร์ไปสู่การ์ด ของใช้ และสื่อดิจิทัล โดยคาแรกเตอร์เป็นสินทรัพย์ที่ต้องรักษาบุคลิกในระยะยาว ขั้นต่อไปที่เสนอคือทำชุดทดลองเพียงสามตัวละครก่อน ประเมินการจดจำ ความชอบ และความเหมาะสมในการผลิต แล้วค่อยขยายจักรวาล ไม่ควรลงทุนสร้างตัวละครจำนวนมากก่อนรู้ว่าตัวใดสื่อสารได้ดี","en":"The concept can grow into cards, accessories and digital media. Begin with a proposed three-character pilot, assess recognisability, preference and production suitability, and expand only when evidence supports it."}}],"storytelling":{"opening":"แบรนด์ Pet Lifestyle สมมติใช้ของแจกและสติกเกอร์ในแคมเปญ แต่เมื่อแคมเปญจบ ภาพกราฟิกแต่ละชุดก็ถูกเก็บไป การสร้างภาพใหม่ทุกครั้งทำให้การจดจำไม่ต่อเนื่อง PAW PARADE จึงเริ่มจากการคิดว่าจะสร้างสินทรัพย์ของแบรนด์ที่มีชีวิตยาวกว่าแคมเปญได้อย่างไร","pain_point":"หากแบรนด์สื่อสารด้วยรูปสัตว์น่ารักทั่วไปเพียงอย่างเดียว ยากที่จะสร้างความแตกต่างและบุคลิกเฉพาะ การวาดตัวละครใหม่โดยไม่มีระบบยังทำให้สัดส่วน สี และน้ำหนักเส้นไม่สม่ำเสมอ","big_idea":"Little Friends, Big Personality — สร้างโลกที่ผู้คนเลือกเพื่อนตัวเล็กซึ่งสะท้อนบุคลิกของตนได้ ให้ความสนุกเกิดจากเรื่องราว ไม่ใช่เพียงจำนวนตัวละคร","logo_rationale":"wordmark กลมมนและรอยเท้าสัตว์เป็นลายเซ็นที่ใช้งานได้แม้ไม่มีตัวละคร สีส้มให้ความสนุกและทำหน้าที่เป็นจุดยึดร่วมในคอลเลกชัน","pattern_rationale":"นำรอยเท้า กระดูก หัวใจ และดาวมาสร้าง Secondary Pattern กำหนดระยะห่างและขนาดให้มีจังหวะ ใช้บนแผ่นรอง ถุง และสื่อออนไลน์โดยไม่ทำให้ตัวละครหลักกลืนไปกับพื้นหลัง","mascot_rationale":"Mascot เป็นแกนของโจทย์: กำหนดคอร์กี้เป็นตัวหลักที่ร่าเริง แมวเป็นเพื่อนขี้สงสัย และแพนด้าเป็นเพื่อนใจเย็น พัฒนาสัดส่วนใบหน้า ท่าทาง และ Expression Sheet เพื่อสร้างเรื่องใหม่โดยยังจำได้ว่าเป็นตัวเดิม ตัวละครสมทบไม่จำเป็นต้องปรากฏทุกชิ้น","application_system":"ทำชุดสติกเกอร์เริ่มต้นและต่อยอดเป็น Seasonal Collection แผ่นรองมีโครงคงที่ เปลี่ยนท่าทางและองค์ประกอบประกอบตามธีม ใช้คาแรกเตอร์สื่อสารความรู้สึกใน Social Content","trade_off":"เส้นบางหรือส่วนยื่นมากอาจไดคัทยาก จึงทำเวอร์ชัน simplified สำหรับขนาดเล็ก แยกเส้นคัตและกราฟิกตามข้อกำหนดของผู้ผลิตจริง","validation_plan":"ทดสอบการจำตัวละครเมื่อเปลี่ยนท่าทาง การอ่านอารมณ์ที่ขนาดเล็ก ความทนต่อการลอกและตัด รวมถึงความสอดคล้องของสีในแต่ละชุด","visual_asset_brief":["Character model sheet และสัดส่วน","Expression และ pose sheet","Secondary pattern","Die-cut sticker collection","Backing card และ seasonal packaging","Macro ขอบไดคัท"]},"deliverables":["Character direction","Sticker collection concept","Die-cut artwork rules","Backing card concept"],"assetNotes":"โลโก้เวกเตอร์ต้นแบบสร้างแยกจากภาพจำลอง อาจมีรายละเอียดไม่ตรงกับโลโก้ใน Mockup ทุกจุด; ภาพ hero และ card มาจากภาพเดียวกัน ไม่ใช่ภาพถ่ายจริง; ชื่อแบรนด์ยังไม่ได้ตรวจสอบสิทธิ์เครื่องหมายการค้า","featured":true},{"brand":"ROAST & RISE","title":"เปลี่ยนกระจกหน้าร้านให้เป็นพื้นที่สื่อสารแบรนด์","summary":"พัฒนากราฟิกหน้าร้านที่สื่อสารแบรนด์และบรรยากาศคาเฟ่ โดยรักษาความโปร่งและการมองเห็นภายใน","headline":{"th":"หน้าร้านที่เชิญชวนให้เดินเข้าไป ไม่ใช่แค่กระจกที่ติดโฆษณา","en":"A storefront that invites people in, not merely glass covered in advertising."},"timeline":[{"step":"01","heading":{"th":"จุดเริ่มต้นและบริบท","en":"Project Brief"},"body":{"th":"คาเฟ่สมมติมีบรรยากาศอบอุ่นภายใน แต่เมื่อมองจากทางเดิน กระจกสะท้อนสภาพแวดล้อมจนคนที่ไม่รู้จักร้านอาจเดินผ่าน การสร้างแบรนด์จึงเริ่มจากจุดสัมผัสก่อนลูกค้าเปิดประตู\n\nคาเฟ่สมมติที่มีหน้าร้านกระจกต้องการสร้างการจดจำจากทางเดินโดยไม่ปิดทัศนวิสัยทั้งหมด กราฟิกต้องทำงานในสภาพแสงกลางวันและกลางคืน และมีพื้นที่ติดตั้งที่เหมาะสม\n\nโครงการสมมตินี้เริ่มจากคาเฟ่ที่ให้ความสำคัญกับช่วงเวลาพักระหว่างวัน ตั้งใจให้พื้นที่ภายในอบอุ่นและเปิดรับผู้คนที่เดินผ่าน แต่จุดสัมผัสแรกของลูกค้าเกิดขึ้นภายนอกอาคาร กระจกจึงไม่ใช่เพียงพื้นผิวสำหรับติดสติกเกอร์ แต่เป็นส่วนหนึ่งของหน้าร้านที่ต้องทำงานร่วมกับแสง เฟอร์นิเจอร์ และการมองเห็นทางเข้า","en":"A hypothetical café wants a warm place to pause. The first contact happens outside the building, so glazing must work with light, furniture, visibility and the entrance rather than act as an isolated advertising surface."}},{"step":"02","heading":{"th":"Pain Point และเหตุผลที่ต้องเปลี่ยน","en":"Insight"},"body":{"th":"การติดกราฟิกเต็มกระจกทำให้เห็นข้อความชัดแต่ปิดบรรยากาศภายใน ขณะที่ปล่อยกระจกโล่งทั้งหมดอาจทำให้ร้านขาดจุดจดจำและแยกประตูจากช่องกระจกได้ยาก\n\nหน้าร้านเป็นทั้งสื่อแบรนด์และทางเข้าสู่ประสบการณ์จริง การใช้ภาพเต็มกระจกอาจดึงดูดสายตาแต่ลดความโปร่ง จึงต้องออกแบบตามแนวสายตาและช่องเปิดของอาคาร\n\nถ้าหน้าร้านติดภาพเครื่องดื่มขนาดใหญ่จนเต็มกระจก คนอาจรู้ว่าขายกาแฟแต่ไม่เห็นบรรยากาศที่เป็นจุดขาย หากไม่มีกราฟิกเลย ชื่อร้านอาจจมหายไปในเงาสะท้อนและกรอบอาคาร การออกแบบต้องตอบทั้งคำถามว่า “ร้านอะไร” “เข้าได้ตรงไหน” และ “บรรยากาศข้างในเหมาะกับฉันหรือไม่” โดยไม่ยัดทุกข้อความไว้ในพื้นที่เดียว","en":"Full-coverage drink imagery can hide the atmosphere; an unmarked facade can disappear behind reflections. The design must identify the café, guide visitors to the door and preserve useful views inside."}},{"step":"03","heading":{"th":"แนวคิดหลักและเหตุผลของอัตลักษณ์","en":"Creative Direction"},"body":{"th":"Warm Welcome — ใช้กราฟิกเป็นเครื่องหมายเชื้อเชิญ ให้ร้านดูเป็นส่วนหนึ่งของพื้นที่โดยไม่ปิดกั้นการมองเห็น\n\nตัวอักษรอบอุ่นและสัญลักษณ์เมล็ดกาแฟทำให้ระบุหมวดร้านได้ทันที โทนน้ำตาลและครีมเชื่อมโยงกับไม้ แสง และบรรยากาศภายใน\n\nWarm Welcome ใช้ภาพลักษณ์ที่ชวนเข้ามามากกว่าการโฆษณาเสียงดัง โทนน้ำตาลคั่วและครีมสัมพันธ์กับเมล็ดกาแฟและแสงอบอุ่น ตัวอักษรและสัญลักษณ์เมล็ดกาแฟต้องอ่านได้จากพื้นที่ทางเดิน ไม่จำเป็นต้องเพิ่มภาพประกอบจนเต็มหน้าร้าน เลือกเส้นโค้งที่ได้แรงบันดาลใจจากไอน้ำเป็นจังหวะนำสายตาไปตามแนวกระจก และเว้นช่องให้เห็นกิจกรรมด้านใน","en":"Warm Welcome — roasted brown and cream echo coffee, wood and warm lighting. A readable wordmark, bean symbol and steam-inspired curves provide an invitation rather than visual noise."}},{"step":"04","heading":{"th":"Pattern, Mascot และระบบการใช้งาน","en":"Design Development"},"body":{"th":"เส้นโค้งเหมือนไอน้ำและลวดลายเมล็ดกาแฟทำหน้าที่นำสายตาตามแนวกระจก ใช้ขนาดใหญ่ที่หน้าร้านและลดขนาดเป็นลายบนแก้ว ไม่ใช้ลายเต็มทุกช่อง\n\nไม่จำเป็นต้องมี Mascot ในทิศทางนี้ เพราะบรรยากาศจริงของร้านและประสบการณ์การดื่มกาแฟเป็นตัวเล่าเรื่องหลัก\n\nวางจุดอ่านชื่อร้านบนกระจกและแบ่งพื้นที่ภาพทึบ/โปร่ง เชื่อมลายเดียวกันไปสู่แก้ว ถุง ป้ายเมนู และสื่อหน้าร้านตามบริบทการอ่าน\n\nจัดระบบกราฟิกตามระยะ: ชื่อร้านและเครื่องหมายเป็นจุดจำจากไกล ลายเส้นและพื้นที่โปร่งทำหน้าที่เชื่อมอาคารกับแบรนด์ ส่วนเมนู เวลาเปิด และข้อมูลที่เปลี่ยนบ่อยควรอยู่ใกล้จุดตัดสินใจและเปลี่ยนได้ง่าย เมื่อต่อยอดลายไอน้ำไปบนแก้ว ถุง หรือการ์ด สามารถครอปส่วนโค้งเดียวกันตามสัดส่วนสื่อ ไม่จำเป็นต้องใส่ Mascot เพราะคนและบรรยากาศของร้านคือเรื่องเล่าที่แข็งแรงกว่าในแนวคิดนี้","en":"Organise the graphics by viewing distance: name and mark from far away, curves and clear zones at middle distance, replaceable menus and hours near decisions. Crop the same steam motif for cups and bags. The actual café experience is the storyteller, so no mascot is required."}},{"step":"05","heading":{"th":"จากแนวคิดสู่การผลิต","en":"Production Strategy"},"body":{"th":"สำรวจระยะและชนิดกระจกจริง เลือกฟิล์มสำหรับงานติดกระจกและด้านติดตั้งให้เหมาะกับวัสดุและสภาพแสง พิจารณาการลอกออก การดูแลรักษา และข้อจำกัดความร้อนตามคำแนะนำผู้ผลิตฟิล์ม\n\nต้องสำรวจชนิดกระจกและความร้อนก่อนเลือกฟิล์ม ออกแบบรอยต่อไม่ให้ผ่านโลโก้หรือข้อความ และไม่กีดขวางการมองเห็นหรือทางเข้า\n\nก่อนผลิตต้องสำรวจขนาดกระจกจริง ระยะกรอบ ชนิดผิว ทิศแดด จุดเปิดปิด และด้านที่เหมาะกับการติดตั้ง เปรียบเทียบฟิล์มทึบ ฟิล์มใสพิมพ์หมึกขาว หรือวัสดุอื่นตามเป้าหมายความโปร่งและข้อกำหนดกระจก รอยต่อระหว่างแผ่นควรหลบตัวอักษร และชิ้นส่วนโปรโมชั่นควรแยกจากกราฟิกถาวรเพื่อให้เปลี่ยนเฉพาะจุดได้โดยไม่รื้อทั้งหมด","en":"Survey every pane, frame, opening, substrate and solar exposure before film selection. Compare opaque and transparent options with white ink where appropriate. Keep seams away from key letters and separate temporary promotions from permanent graphics."}},{"step":"06","heading":{"th":"การทดสอบและตรวจสอบ","en":"Quality Control"},"body":{"th":"ตรวจแบบจำลองจากมุมผู้เดินผ่าน รอยต่อภาพ ความเรียบของฟิล์ม การมองเห็นป้ายและประตู รวมถึงความเข้ากันได้ของวัสดุกับกระจกก่อนติดตั้ง\n\nทำภาพจำลองจากมุมผู้เดินผ่านและมุมกลางคืน ตรวจการอ่านชื่อร้านและความโปร่งของกระจก ทดลองติดฟิล์มบนตัวอย่างก่อนเลือกสเปก\n\nสร้าง mockup จากภาพถ่ายหน้าร้านจริงเมื่อมีสถานที่ และเปรียบเทียบจากมุมทางเดินทั้งสองด้าน รวมถึงสภาพแสงกลางวันและกลางคืน ตรวจความชัดของชื่อร้าน ประตู และการมองเห็นด้านใน ทดลองติดตัวอย่างวัสดุบนพื้นที่ที่ได้รับอนุญาต ตรวจขอบฟิล์ม รอยต่อ และข้อจำกัดด้านความร้อนกับผู้ผลิต ก่อนล็อกแบบสำหรับติดตั้ง","en":"When a site is available, mock up actual photographs from both walking directions in day and night conditions. Trial stock on permitted glazing and confirm visibility, adhesion, seams, heat constraints and installation with the supplier."}},{"step":"07","heading":{"th":"คุณค่าที่คาดหวัง","en":"Concept Outcome"},"body":{"th":"แนวคิดแสดงให้เห็นว่ากราฟิกหน้าร้านสามารถเชื่อมภาพลักษณ์กับประสบการณ์ในร้านได้ พร้อมแนวทางติดตั้งที่ตรวจสอบได้ ยังไม่มีการสำรวจหรือติดตั้งจริง\n\nคุณค่าที่ออกแบบไว้คือการทำให้ภาพแบรนด์เชื่อมกับประสบการณ์ก่อนเข้าร้าน ระหว่างซื้อ และหลังถือแก้วออกไป โดยไม่ต้องเปลี่ยนกราฟิกหน้าร้านทั้งชุดตามทุกโปรโมชั่น เมื่อมีสถานที่จริงจึงค่อยประเมินจากการหาทางเข้า ความอ่านง่าย และความเห็นของผู้ใช้ พร้อมเก็บข้อมูลการดูแลและเปลี่ยนชิ้นงานเพื่อปรับระบบให้เหมาะกับการใช้งานระยะยาว","en":"Connect the arrival, purchase and takeaway experience without replacing the entire storefront for each campaign. Evaluate entrance finding, legibility and maintenance only when an actual site is available."}}],"storytelling":{"opening":"คาเฟ่สมมติมีบรรยากาศอบอุ่นภายใน แต่เมื่อมองจากทางเดิน กระจกสะท้อนสภาพแวดล้อมจนคนที่ไม่รู้จักร้านอาจเดินผ่าน การสร้างแบรนด์จึงเริ่มจากจุดสัมผัสก่อนลูกค้าเปิดประตู","pain_point":"การติดกราฟิกเต็มกระจกทำให้เห็นข้อความชัดแต่ปิดบรรยากาศภายใน ขณะที่ปล่อยกระจกโล่งทั้งหมดอาจทำให้ร้านขาดจุดจดจำและแยกประตูจากช่องกระจกได้ยาก","big_idea":"Warm Welcome — ใช้กราฟิกเป็นเครื่องหมายเชื้อเชิญ ให้ร้านดูเป็นส่วนหนึ่งของพื้นที่โดยไม่ปิดกั้นการมองเห็น","logo_rationale":"ตัวอักษรอบอุ่นและสัญลักษณ์เมล็ดกาแฟทำให้ระบุหมวดร้านได้ทันที โทนน้ำตาลและครีมเชื่อมโยงกับไม้ แสง และบรรยากาศภายใน","pattern_rationale":"เส้นโค้งเหมือนไอน้ำและลวดลายเมล็ดกาแฟทำหน้าที่นำสายตาตามแนวกระจก ใช้ขนาดใหญ่ที่หน้าร้านและลดขนาดเป็นลายบนแก้ว ไม่ใช้ลายเต็มทุกช่อง","mascot_rationale":"ไม่จำเป็นต้องมี Mascot ในทิศทางนี้ เพราะบรรยากาศจริงของร้านและประสบการณ์การดื่มกาแฟเป็นตัวเล่าเรื่องหลัก","application_system":"วางจุดอ่านชื่อร้านบนกระจกและแบ่งพื้นที่ภาพทึบ/โปร่ง เชื่อมลายเดียวกันไปสู่แก้ว ถุง ป้ายเมนู และสื่อหน้าร้านตามบริบทการอ่าน","trade_off":"ต้องสำรวจชนิดกระจกและความร้อนก่อนเลือกฟิล์ม ออกแบบรอยต่อไม่ให้ผ่านโลโก้หรือข้อความ และไม่กีดขวางการมองเห็นหรือทางเข้า","validation_plan":"ทำภาพจำลองจากมุมผู้เดินผ่านและมุมกลางคืน ตรวจการอ่านชื่อร้านและความโปร่งของกระจก ทดลองติดฟิล์มบนตัวอย่างก่อนเลือกสเปก","visual_asset_brief":["Storefront before concept schematic","Logo และ steam/bean motif","Window layout ตามช่องกระจก","Cup and takeaway applications","ภาพจำลองหน้าร้านกลางวันและกลางคืน"]},"deliverables":["Storefront visual direction","Window zoning","Installation concept","Site survey checklist"],"assetNotes":"โลโก้เวกเตอร์ต้นแบบสร้างแยกจากภาพจำลอง อาจมีรายละเอียดไม่ตรงกับโลโก้ใน Mockup ทุกจุด; ภาพ hero และ card มาจากภาพเดียวกัน ไม่ใช่ภาพถ่ายจริง; ชื่อแบรนด์ยังไม่ได้ตรวจสอบสิทธิ์เครื่องหมายการค้า","featured":true},{"brand":"FORMLINE","title":"สร้างระบบสติกเกอร์ที่รองรับหลายรูปแบบการผลิต","summary":"วางระบบโลโก้และไฟล์สติกเกอร์สำหรับงานม้วน งานแผ่น และงานไดคัท ให้จัดการง่ายตั้งแต่ต้นแบบ","headline":{"th":"หนึ่งอัตลักษณ์ หลายรูปแบบการผลิต โดยไม่ต้องเริ่มออกแบบใหม่ทุกครั้ง","en":"One identity across many production formats, without redesigning every time."},"timeline":[{"step":"01","heading":{"th":"จุดเริ่มต้นและบริบท","en":"Project Brief"},"body":{"th":"เมื่อแบรนด์สมมติเติบโตจากการใช้สติกเกอร์เพียงขนาดเดียวไปสู่กล่อง เอกสาร และงานม้วน การส่งโลโก้ต่อกันหลายคนอาจทำให้เกิดไฟล์หลายเวอร์ชัน FORMLINE จึงมองอัตลักษณ์เป็นระบบที่ต้องส่งต่อได้\n\nแบรนด์สมมติต้องใช้สติกเกอร์กับกล่องสินค้า เอกสารจัดส่ง และของพรีเมียมหลายขนาด การสร้าง artwork ใหม่ทุกครั้งทำให้เกิดความเสี่ยงด้านสัดส่วน สี และการตั้งชื่อไฟล์\n\nFORMLINE ตั้งต้นจากแบรนด์สมมติที่ใช้สติกเกอร์เป็นส่วนหนึ่งของการจัดส่งและการสื่อสารกับลูกค้า เมื่อปริมาณงานเพิ่มขึ้น สติกเกอร์ไม่ได้อยู่กับสินค้าเพียงรูปแบบเดียว แต่ปรากฏบนกล่อง ฉลากม้วน และวัสดุส่งเสริมการขาย คนที่ใช้งานระบบจึงรวมถึงฝ่ายออกแบบ ฝ่ายจัดซื้อ และผู้ผลิต ไม่ใช่เฉพาะผู้บริโภคปลายทาง","en":"A hypothetical brand uses stickers on packaging, rolls, sheets and promotions. Its system must support designers, purchasers and production partners as well as end users."}},{"step":"02","heading":{"th":"Pain Point และเหตุผลที่ต้องเปลี่ยน","en":"Insight"},"body":{"th":"ความเสี่ยงไม่ได้อยู่ที่ความสวยของโลโก้อย่างเดียว แต่เกิดจากการย่อผิดสัดส่วน การใช้สีไม่ตรง และการใช้เส้นตัดผิดชุด ซึ่งอาจทำให้ต้องแก้ไฟล์ก่อนผลิตซ้ำ\n\nระบบ production ที่ดีเริ่มจาก master asset ที่ไม่ขึ้นกับรูปแบบการส่งมอบ แล้วกำหนดกติกาเฉพาะงานม้วนและงานแผ่น ไม่ใช้ไฟล์ที่เหมาะกับเครื่องหนึ่งไปแทนอีกเครื่องโดยตรง\n\nสมมติว่าฝ่ายจัดซื้อส่งไฟล์โลโก้จากงานเก่าให้โรงพิมพ์ ขณะที่ทีมออกแบบเปลี่ยนสีหรือขนาดในอีกเวอร์ชัน ผลงานอาจยังดูคล้ายกันแต่ไม่ใช่มาตรฐานเดียวกัน ยิ่งมีงานม้วนกับงานแผ่น การใช้เส้นตัดหรือทิศคลายม้วนผิดอาจทำให้เกิดงานแก้ไข ปัญหาจึงเป็นเรื่องของการจัดการ Asset และ Production Handoff มากกว่าการรีเฟรชหน้าตาแบรนด์","en":"Old logos, colour revisions, cut paths and unwind directions can get mixed up across departments. This is an asset management and production handoff problem rather than simply a visual refresh."}},{"step":"03","heading":{"th":"แนวคิดหลักและเหตุผลของอัตลักษณ์","en":"Creative Direction"},"body":{"th":"One Identity, Many Applications — สร้าง master asset และกติกาที่คนออกแบบกับโรงงานใช้ร่วมกันได้\n\nสัญลักษณ์สองสีที่ลดทอนได้ง่ายเหมาะกับงานขนาดเล็ก Navy และส้มทำหน้าที่เป็นคู่สีหลัก มีแนวทางสีเดียวเมื่อข้อจำกัดเครื่องพิมพ์ต้องการ\n\nOne Identity, Many Applications วางโลโก้เป็นชิ้นส่วนกลางของระบบ รูปทรงสีน้ำเงินและส้มที่ต่อกันสื่อความต่อเนื่องและสามารถลดทอนเป็นสีเดียวได้ โดยยังรักษาโครงเดิม สีที่แสดงบนจอเป็นเพียงจุดเริ่มต้นของการกำหนดสีอ้างอิง ไม่ใช่สูตรหมึกที่ใช้ได้กับทุกวัสดุ ความเป็นมืออาชีพจึงเกิดจากกติกาที่ชัดและทำซ้ำได้ ไม่ใช่การเพิ่มองค์ประกอบใหม่ทุกครั้ง","en":"One Identity, Many Applications — a simple two-colour navy/orange mark becomes the shared master asset, with a monochrome version for appropriate production constraints. Physical proof, not screen colour alone, determines approved output."}},{"step":"04","heading":{"th":"Pattern, Mascot และระบบการใช้งาน","en":"Design Development"},"body":{"th":"ต่อยอดรูปทรงจากสัญลักษณ์เป็นโมดูลซ้ำแบบครอป ใช้บนกล่องและแผ่นรองเพื่อให้จดจำได้โดยไม่ต้องพิมพ์โลโก้ทุกตำแหน่ง ไม่ใช้ Pattern ในบริเวณบาร์โค้ดหรือข้อความสำคัญ\n\nไม่ใช้ Mascot เพราะปัญหาหลักคือการควบคุมระบบอัตลักษณ์และการผลิต ไม่ใช่การสร้างตัวละครสำหรับแคมเปญ\n\nกำหนด master logo, icon-only, monochrome และขนาดขั้นต่ำ แยก template งานม้วนและงานแผ่น พร้อมชื่อไฟล์ revision และ layer Artwork/Die-cut\n\nนำส่วนโค้งและแนวเฉียงของสัญลักษณ์มาทำ Modular Pattern ที่ต่อกันได้บนกล่องหรือแผ่นรอง โดยกำหนดว่าพื้นที่บาร์โค้ดและข้อมูลขนส่งต้องไม่มีลายรบกวน จัดชุด master logo แบบหลัก แบบไอคอน และแบบสีเดียว กำหนดกริดและพื้นที่ว่าง แล้วแยกแม่แบบตามประเภทงาน Mascot ไม่จำเป็น เพราะคนใช้ระบบต้องรู้ว่าหยิบไฟล์ไหนไปใช้และใช้อย่างไร มากกว่าต้องการตัวละครเพิ่ม","en":"Derive cropped repeat modules from the mark while keeping barcodes and essential copy clear. Define locked brand elements and separate templates for different applications, with an asset library and revision conventions. No mascot is needed for this operational identity."}},{"step":"05","heading":{"th":"จากแนวคิดสู่การผลิต","en":"Production Strategy"},"body":{"th":"ระบุชนิดวัสดุ กาว ระยะห่างระหว่างชิ้น และทิศทางคลายม้วนตามเครื่องติดฉลากจริง สำหรับงานแผ่นกำหนด layout ตามพื้นที่พิมพ์และระยะตัดที่ supplier ยืนยัน\n\nการใช้ไฟล์เดียวกับทุกเครื่องสะดวกแต่เสี่ยงต่อระยะตัดและทิศคลายม้วน จึงคง master เดียวแต่แยก production template ตามสเปกจริง\n\nวางแผนการส่งมอบโดยแยก Artwork กับ Die-cut เป็นเลเยอร์ที่ตรวจสอบและเปิดปิดได้ในไฟล์ต้นฉบับ พร้อมกำหนดสเปกเส้นตัดตามผู้ผลิต สำหรับงานม้วนต้องตกลงแกนม้วน ทิศคลาย ระยะห่าง และลักษณะการติดฉลาก ส่วนงานแผ่นต้องคำนึงถึงขนาดแผ่นและการจัดวางที่เหมาะสม ใช้ชื่อไฟล์ระบุ SKU ขนาด และ revision เพื่อไม่ให้ไฟล์ที่หน้าตาคล้ายกันถูกนำไปผลิตผิดประเภท","en":"Keep the master graphic stable but prepare separate sheet, roll and individual cut layouts against actual machine requirements. Confirm registration, cut clearance, core, unwind direction and gaps where applicators are used. Avoid treating one file as universal."}},{"step":"06","heading":{"th":"การทดสอบและตรวจสอบ","en":"Quality Control"},"body":{"th":"ตรวจขนาด 1:1 เลเยอร์เส้นตัด ความตรงของสี ความทนของกาว และทิศทางการคลายม้วน ตรวจ proof ก่อนอนุมัติแต่ละรูปแบบ\n\nทดลองจัดวางโลโก้หลายขนาด ตรวจสีอ้างอิงและขนาดขั้นต่ำ ตรวจทิศคลายม้วนและเส้นตัดกับ supplier ก่อนอนุมัติ\n\nสร้างชุดตัวอย่างงานขนาดเล็ก กลาง และใหญ่ แล้วตรวจว่าสัญลักษณ์ยังอ่านได้และคงสัดส่วน ตรวจปรู๊ฟทั้งสีและขนาดจริง พร้อมเปิดปิดเลเยอร์เพื่อตรวจว่าเส้นตัดไม่ถูกปะปนกับกราฟิก ทดสอบการส่งไฟล์ให้ผู้ใช้งานอีกคนโดยไม่อธิบายปากเปล่า หากยังเลือกไฟล์ไม่ถูก ให้ปรับ naming convention หรือคู่มือก่อนนำระบบไปใช้จริง","en":"Review actual-size graphics, proof colours and test cuts for every delivery format. Trial peeling or feeding, reconcile SKU identifiers and counts, and document agreed revisions and acceptance checks."}},{"step":"07","heading":{"th":"คุณค่าที่คาดหวัง","en":"Concept Outcome"},"body":{"th":"ต้นแบบนำเสนอระบบงานที่มี master asset เดียวและข้อกำหนดแยกตามประเภทชิ้นงาน ช่วยวางแผนลดการแก้ไฟล์ซ้ำ แต่ยังไม่มีข้อมูลการลดเวลาและต้นทุนที่วัดจริง\n\nผลที่คาดหวังคือคนหลายฝ่ายสามารถใช้ทรัพยากรชุดเดียวกันโดยไม่ต้องตีความใหม่ทุกครั้ง เมื่อมีงานประเภทใหม่ ให้เพิ่ม production template แต่ไม่เปลี่ยน master โดยไม่มีเหตุผล ตัวชี้วัดที่เหมาะสมในอนาคตคือจำนวนไฟล์ที่ต้องแก้ก่อนผลิต จำนวนความคลาดเคลื่อนของเวอร์ชัน และระยะเวลาที่ใช้เตรียมงานซ้ำ ทั้งหมดยังเป็นเป้าหมายสำหรับการทดสอบ ไม่ใช่ผลที่เกิดขึ้นแล้ว","en":"The proposed system should make new applications easier to brief and verify. Evaluate revision errors, recognition and handoff effort with actual work; the concept does not claim measured savings."}}],"storytelling":{"opening":"เมื่อแบรนด์สมมติเติบโตจากการใช้สติกเกอร์เพียงขนาดเดียวไปสู่กล่อง เอกสาร และงานม้วน การส่งโลโก้ต่อกันหลายคนอาจทำให้เกิดไฟล์หลายเวอร์ชัน FORMLINE จึงมองอัตลักษณ์เป็นระบบที่ต้องส่งต่อได้","pain_point":"ความเสี่ยงไม่ได้อยู่ที่ความสวยของโลโก้อย่างเดียว แต่เกิดจากการย่อผิดสัดส่วน การใช้สีไม่ตรง และการใช้เส้นตัดผิดชุด ซึ่งอาจทำให้ต้องแก้ไฟล์ก่อนผลิตซ้ำ","big_idea":"One Identity, Many Applications — สร้าง master asset และกติกาที่คนออกแบบกับโรงงานใช้ร่วมกันได้","logo_rationale":"สัญลักษณ์สองสีที่ลดทอนได้ง่ายเหมาะกับงานขนาดเล็ก Navy และส้มทำหน้าที่เป็นคู่สีหลัก มีแนวทางสีเดียวเมื่อข้อจำกัดเครื่องพิมพ์ต้องการ","pattern_rationale":"ต่อยอดรูปทรงจากสัญลักษณ์เป็นโมดูลซ้ำแบบครอป ใช้บนกล่องและแผ่นรองเพื่อให้จดจำได้โดยไม่ต้องพิมพ์โลโก้ทุกตำแหน่ง ไม่ใช้ Pattern ในบริเวณบาร์โค้ดหรือข้อความสำคัญ","mascot_rationale":"ไม่ใช้ Mascot เพราะปัญหาหลักคือการควบคุมระบบอัตลักษณ์และการผลิต ไม่ใช่การสร้างตัวละครสำหรับแคมเปญ","application_system":"กำหนด master logo, icon-only, monochrome และขนาดขั้นต่ำ แยก template งานม้วนและงานแผ่น พร้อมชื่อไฟล์ revision และ layer Artwork/Die-cut","trade_off":"การใช้ไฟล์เดียวกับทุกเครื่องสะดวกแต่เสี่ยงต่อระยะตัดและทิศคลายม้วน จึงคง master เดียวแต่แยก production template ตามสเปกจริง","validation_plan":"ทดลองจัดวางโลโก้หลายขนาด ตรวจสีอ้างอิงและขนาดขั้นต่ำ ตรวจทิศคลายม้วนและเส้นตัดกับ supplier ก่อนอนุมัติ","visual_asset_brief":["Master logo variations","Module pattern system","Roll vs sheet layout","Artwork / die-cut layer diagram","ตัวอย่าง mockup การใช้งานหลายขนาด"]},"deliverables":["Logo master","Sticker system concept","Artwork / Die-cut convention","Version & QC checklist"],"assetNotes":"โลโก้เวกเตอร์ต้นแบบสร้างแยกจากภาพจำลอง อาจมีรายละเอียดไม่ตรงกับโลโก้ใน Mockup ทุกจุด; ภาพ hero และ card มาจากภาพเดียวกัน ไม่ใช่ภาพถ่ายจริง; ชื่อแบรนด์ยังไม่ได้ตรวจสอบสิทธิ์เครื่องหมายการค้า","featured":true},{"brand":"MELLOW GRAIN","title":"พัฒนาแพ็กเกจอาหารให้เลือกสินค้าได้ง่ายและขยายไลน์ได้","summary":"วางระบบกราฟิกบนซองและกล่องสำหรับผลิตภัณฑ์ธัญพืช โดยให้ชื่อรสชาติและข้อมูลสินค้าอ่านง่าย","headline":{"th":"ความน่ากินที่มาพร้อมระบบการเลือกซื้อและขยายรสชาติ","en":"An appetising food range that is easier to shop and extend."},"timeline":[{"step":"01","heading":{"th":"จุดเริ่มต้นและบริบท","en":"Project Brief"},"body":{"th":"แบรนด์กราโนลาสมมติเริ่มจากรสน้ำผึ้งอัลมอนด์และต้องการเพิ่มรสเบอร์รี เมื่อสินค้าอยู่ร่วมกันบนชั้น ภาพและชื่อรสต้องสื่อสารได้อย่างรวดเร็วโดยไม่ทำให้ผู้ซื้อคิดว่าเป็นคนละแบรนด์\n\nโจทย์สมมติสำหรับกราโนลาหลายรสชาติ ต้องการแพ็กเกจที่ดูอบอุ่นและมีคุณค่า แต่ยังต้องสื่อชื่อรสชาติและข้อมูลสำคัญบนพื้นที่จำกัดของซอง\n\nMELLOW GRAIN เป็นแบรนด์อาหารเช้าสมมติที่ต้องการเข้าถึงคนที่มีเวลาจำกัดแต่ยังสนใจรสชาติและวัตถุดิบ การเริ่มจากกราโนลารสเดียวทำให้การออกแบบครั้งแรกค่อนข้างง่าย แต่เมื่อเพิ่มรสและขนาดบรรจุภัณฑ์ ความต้องการเปลี่ยนจากการสร้างถุงสวยหนึ่งใบเป็นการจัดระบบสินค้าให้ผู้ซื้อเห็นความสัมพันธ์ระหว่างแต่ละสูตรได้ตั้งแต่หน้าชั้นวาง","en":"A hypothetical grain-food range wants an inviting everyday identity across flavours and pack sizes. Shoppers need to see what they are choosing as well as enjoy the food imagery."}},{"step":"02","heading":{"th":"Pain Point และเหตุผลที่ต้องเปลี่ยน","en":"Insight"},"body":{"th":"การใช้รูปอาหารอย่างเดียวอาจไม่ทำให้จำแบรนด์ได้ และการเปลี่ยนสีทั้งซองในแต่ละรสอาจทำให้ภาพรวมไม่สม่ำเสมอ ข้อมูลส่วนประกอบและข้อควรระวังยังต้องอ่านได้\n\nผู้ซื้ออาหารต้องประเมินทั้งความน่ากินและข้อมูลที่จำเป็น ระบบแพ็กเกจที่อิงเพียงสีอาจสร้างความสับสนเมื่อขยาย SKU จึงต้องใช้ชื่อและลำดับข้อมูลร่วมกัน\n\nหากใช้ภาพวัตถุดิบขนาดใหญ่ทุกสูตรโดยไม่มีกริดร่วม สินค้าอาจน่ากินเมื่อดูแยกกันแต่ไม่เกิดภาพครอบครัวเมื่อเรียงรวมกัน ขณะเดียวกัน การใช้กราฟิกเหมือนกันทั้งหมดก็ทำให้ผู้ซื้อหยิบผิดรสได้ โจทย์จึงต้องสร้างความแตกต่างที่มีระบบ และเผื่อพื้นที่ข้อมูลอาหารที่อ่านได้จริง โดยไม่ทำให้การเพิ่มสูตรใหม่กระทบงานเดิมทั้งชุด","en":"When ingredient imagery and flavour colours compete, customers can confuse variants or lose the brand. Maintain shared recognition while making flavour, size and required product information clear."}},{"step":"03","heading":{"th":"แนวคิดหลักและเหตุผลของอัตลักษณ์","en":"Creative Direction"},"body":{"th":"Everyday Goodness — ทำให้ความเรียบง่ายของอาหารประจำวันดูอบอุ่นและเป็นระบบ\n\nSerif และสัญลักษณ์เมล็ดธัญพืชให้บุคลิกงานคราฟต์แบบร่วมสมัย ใช้พื้นสีอบอุ่นเป็นฐานร่วมโดยไม่สื่อสรรพคุณที่ยังไม่ยืนยัน\n\nEveryday Goodness ตีความความเรียบง่ายของมื้อเช้าเป็นความอบอุ่นที่ไม่ซับซ้อน สีทองอมน้ำตาลสื่อถึงธัญพืชและบรรยากาศการอบ ไม่ได้ทำหน้าที่รับรองประโยชน์ต่อสุขภาพ ตัว Serif และสัญลักษณ์เมล็ดสร้างบุคลิกงานคราฟต์ ส่วนชื่อรสและรายละเอียดใช้ตัวอักษรที่อ่านง่ายกว่าเพื่อแบ่งบทบาทระหว่างอารมณ์ของแบรนด์กับข้อมูลประกอบการเลือกซื้อ","en":"Everyday Goodness — warm base colours, a contemporary serif and a grain mark create a crafted but approachable character. Food imagery and flavour identifiers carry information; avoid unverified nutritional claims."}},{"step":"04","heading":{"th":"Pattern, Mascot และระบบการใช้งาน","en":"Design Development"},"body":{"th":"สร้างลายเส้นธัญพืชและริ้วทุ่งข้าวแบบกราฟิก ใช้บนพื้นที่ข้างซองหรือกล่อง ให้ภาพอาหารและแถบรสชาติเด่นกว่าลาย ชนิดเมล็ดที่นำมาใช้ควรสอดคล้องกับสูตรจริงเมื่อผลิต\n\nไม่ใช้ Mascot เพราะทิศทางนี้เน้นข้อมูลอาหารและภาพวัตถุดิบ หากขยายไปกลุ่มเด็กจึงค่อยประเมินใหม่\n\nใช้โครงหน้าและหลังซองคงที่ เปลี่ยนชื่อรส แถบสี และภาพประกอบตามสูตร วางข้อมูลที่เจ้าของสินค้าต้องตรวจรับรองก่อนพิมพ์\n\nวางชื่อ MELLOW GRAIN และตำแหน่งชื่อรสไว้ในกริดเดียวกันทุกซอง น้ำผึ้งอัลมอนด์ใช้สีอุ่นและภาพส่วนประกอบที่เกี่ยวข้อง ส่วนเบอร์รีใช้แถบสีแดงอมม่วงในกรอบเดิม ลายธัญพืชกับแนวริ้วทุ่งทำหน้าที่เชื่อมซองและกล่อง โดยให้พื้นที่ด้านข้างหรือขอบเป็นพื้นที่เล่าเรื่อง ไม่แข่งขันกับภาพอาหารและข้อมูลสำคัญ ไม่ใช้ Mascot เพราะภาพวัตถุดิบและความชัดของรสเป็นแกนหลักของการตัดสินใจในกลุ่มเป้าหมายนี้","en":"Use grain lines and field-inspired motifs on secondary areas, keeping the flavour name and food imagery prominent. Hold a common grid and vary names, accent colours and pack sizes. Ingredient imagery must match the confirmed recipe; no mascot is proposed."}},{"step":"05","heading":{"th":"จากแนวคิดสู่การผลิต","en":"Production Strategy"},"body":{"th":"พิจารณาโครงสร้างฟิล์มลามิเนตและคุณสมบัติกั้นความชื้น/ออกซิเจนตามอายุสินค้า ตรวจความเข้ากันได้ของบรรจุภัณฑ์กับอาหารและเครื่องบรรจุ วางกราฟิกหลบพื้นที่ซีล\n\nความสวยของซองต้องไม่แลกกับคุณสมบัติกั้นความชื้นหรือรอยซีล จึงเริ่มจากสเปกอาหารและเครื่องบรรจุก่อนเลือกฟิล์มและเทคนิคพิมพ์\n\nก่อนเลือกพื้นผิวซอง ต้องทราบลักษณะอาหาร อายุการเก็บที่ต้องการ และวิธีบรรจุจริง ซองด้านอาจให้บุคลิกอบอุ่น แต่โครงสร้างฟิล์มและรอยซีลต้องตอบโจทย์การเก็บรักษาก่อนเรื่องสัมผัส หากใช้หน้าต่างใส ต้องประเมินการปกป้องอาหารและตำแหน่งที่ไม่เบียดกราฟิก เตรียมแม่แบบตาม dieline ที่ผู้ผลิตยืนยันและให้เจ้าของผลิตภัณฑ์ตรวจข้อความ ส่วนประกอบ และข้อมูลสารก่อภูมิแพ้ก่อนอนุมัติพิมพ์","en":"Start with the food, barrier needs, filling and sealing process rather than appearance alone. Confirm film structure, print process, seal areas and owner-approved ingredients, allergens and required copy with qualified suppliers before artwork approval."}},{"step":"06","heading":{"th":"การทดสอบและตรวจสอบ","en":"Quality Control"},"body":{"th":"ตรวจตำแหน่งซีล ความอ่านง่าย ข้อมูลสารก่อภูมิแพ้ตามข้อมูลจริง และสีระหว่างวัสดุ ตรวจต้นแบบบรรจุและผลทดสอบอายุสินค้าจากผู้ผลิตก่อนผลิตจริง\n\nทดสอบการระบุรสและชื่อแบรนด์จากระยะชั้นวาง ตรวจข้อความที่จำเป็น ความเข้ากันได้ของฟิล์มกับอาหารและการซีลตามสเปกจริง\n\nทดสอบภาพรวมสาม SKU บนชั้นจำลองโดยให้ผู้ซื้อระบุแบรนด์ ชื่อรส และขนาดจากมุมมองด้านหน้า จากนั้นตรวจตัวอย่างซองหลังบรรจุว่าข้อความถูกพับหรือบิดบริเวณรอยซีลหรือไม่ ให้ผู้ผลิตทดสอบความเหมาะสมของโครงสร้างฟิล์ม การซีล และการเก็บรักษาตามสเปกจริง การประเมินด้านภาพต้องแยกจากการยืนยันความปลอดภัยของบรรจุภัณฑ์","en":"Test a simulated three-SKU shelf for brand, flavour and size identification. Review filled prototypes for folds and readability near seals; have the producer validate film, sealing and storage against actual requirements, separately from graphic assessment."}},{"step":"07","heading":{"th":"คุณค่าที่คาดหวัง","en":"Concept Outcome"},"body":{"th":"แนวคิดแสดงระบบแพ็กเกจที่ต่อยอดรสชาติได้โดยคงโครงหลักเดิม พร้อมรายการข้อมูลที่ต้องตรวจสอบก่อนใช้งานจริง ไม่ใช่ผลิตภัณฑ์อาหารที่ผ่านการรับรอง\n\nระบบที่ตั้งใจสร้างจะช่วยให้ทีมเพิ่มรสชาติหรือเปลี่ยนขนาดได้โดยรักษาลำดับข้อมูลเดิม และช่วยให้ผู้ซื้อเข้าใจความแตกต่างโดยไม่ต้องอ่านทุกด้านของซอง เมื่อมีผลทดสอบจึงค่อยสรุปว่าการแบ่งสีและกริดช่วยลดความสับสนได้หรือไม่ ในระยะถัดไปสามารถทดลองขยายสู่กล่องของขวัญหรือชุดทดลองหลายรสโดยใช้แม่แบบเดียวกัน","en":"A shared framework can support new flavours, sizes and gift or trial packs. Measure selection clarity in future trials and retain the existing information hierarchy when extending the range."}}],"storytelling":{"opening":"แบรนด์กราโนลาสมมติเริ่มจากรสน้ำผึ้งอัลมอนด์และต้องการเพิ่มรสเบอร์รี เมื่อสินค้าอยู่ร่วมกันบนชั้น ภาพและชื่อรสต้องสื่อสารได้อย่างรวดเร็วโดยไม่ทำให้ผู้ซื้อคิดว่าเป็นคนละแบรนด์","pain_point":"การใช้รูปอาหารอย่างเดียวอาจไม่ทำให้จำแบรนด์ได้ และการเปลี่ยนสีทั้งซองในแต่ละรสอาจทำให้ภาพรวมไม่สม่ำเสมอ ข้อมูลส่วนประกอบและข้อควรระวังยังต้องอ่านได้","big_idea":"Everyday Goodness — ทำให้ความเรียบง่ายของอาหารประจำวันดูอบอุ่นและเป็นระบบ","logo_rationale":"Serif และสัญลักษณ์เมล็ดธัญพืชให้บุคลิกงานคราฟต์แบบร่วมสมัย ใช้พื้นสีอบอุ่นเป็นฐานร่วมโดยไม่สื่อสรรพคุณที่ยังไม่ยืนยัน","pattern_rationale":"สร้างลายเส้นธัญพืชและริ้วทุ่งข้าวแบบกราฟิก ใช้บนพื้นที่ข้างซองหรือกล่อง ให้ภาพอาหารและแถบรสชาติเด่นกว่าลาย ชนิดเมล็ดที่นำมาใช้ควรสอดคล้องกับสูตรจริงเมื่อผลิต","mascot_rationale":"ไม่ใช้ Mascot เพราะทิศทางนี้เน้นข้อมูลอาหารและภาพวัตถุดิบ หากขยายไปกลุ่มเด็กจึงค่อยประเมินใหม่","application_system":"ใช้โครงหน้าและหลังซองคงที่ เปลี่ยนชื่อรส แถบสี และภาพประกอบตามสูตร วางข้อมูลที่เจ้าของสินค้าต้องตรวจรับรองก่อนพิมพ์","trade_off":"ความสวยของซองต้องไม่แลกกับคุณสมบัติกั้นความชื้นหรือรอยซีล จึงเริ่มจากสเปกอาหารและเครื่องบรรจุก่อนเลือกฟิล์มและเทคนิคพิมพ์","validation_plan":"ทดสอบการระบุรสและชื่อแบรนด์จากระยะชั้นวาง ตรวจข้อความที่จำเป็น ความเข้ากันได้ของฟิล์มกับอาหารและการซีลตามสเปกจริง","visual_asset_brief":["Wordmark และ grain illustration","Flavor architecture","Pouch family mockup","Front/back information grid","Macro seal และ material concept"]},"deliverables":["SKU design system","Pouch & carton concept","Front/back information architecture","Production readiness checklist"],"assetNotes":"โลโก้เวกเตอร์ต้นแบบสร้างแยกจากภาพจำลอง อาจมีรายละเอียดไม่ตรงกับโลโก้ใน Mockup ทุกจุด; ภาพ hero และ card มาจากภาพเดียวกัน ไม่ใช่ภาพถ่ายจริง; ชื่อแบรนด์ยังไม่ได้ตรวจสอบสิทธิ์เครื่องหมายการค้า","featured":true},{"brand":"ELITECRAFT","title":"ยกระดับภาพลักษณ์สินค้า Home Fragrance","summary":"วางแนวทางฉลากและกล่องพรีเมียมที่ใช้ฟอยล์และผิวสัมผัสอย่างมีจุดหมาย ไม่เพิ่มต้นทุนโดยไม่จำเป็น","headline":{"th":"ความพรีเมียมที่เกิดจากรายละเอียด ไม่ใช่การใส่เอฟเฟกต์ให้มากที่สุด","en":"Premium value comes from deliberate detail, not the maximum number of effects."},"timeline":[{"step":"01","heading":{"th":"จุดเริ่มต้นและบริบท","en":"Project Brief"},"body":{"th":"แบรนด์เทียนหอมสมมติต้องการให้กระปุกและกล่องสื่อถึงประสบการณ์การให้ของขวัญ แต่หากใช้สีทองและเทคนิคพิเศษเต็มพื้นที่ทุกชิ้น อาจดูหนักและเพิ่มต้นทุนโดยไม่สร้างจุดจดจำ\n\nแบรนด์เทียนหอมสมมติต้องการให้สินค้าสื่อคุณภาพผ่านรายละเอียดวัสดุและงานตกแต่ง โดยยังรักษาความสม่ำเสมอระหว่างกระปุกและกล่องของขวัญ\n\nโจทย์ ELITECRAFT สมมติให้เทียนหอมเป็นของใช้ที่มีบทบาททั้งในบ้านและการให้ของขวัญ ผู้ซื้อไม่ได้ประเมินแค่กลิ่น แต่ยังสัมผัสผิวกระปุก เห็นกล่อง และรับรู้ความใส่ใจในรายละเอียด แบรนด์จึงต้องสื่อความประณีตก่อนที่จะมีโอกาสทดลองกลิ่น โดยไม่จำเป็นต้องทำให้ทุกชิ้นงานมีต้นทุนเท่ากับรุ่นพิเศษ","en":"A hypothetical scented-candle collection is experienced through the jar, carton and touch as well as fragrance. The brief is to express craft without requiring every SKU to carry gift-edition costs."}},{"step":"02","heading":{"th":"Pain Point และเหตุผลที่ต้องเปลี่ยน","en":"Insight"},"body":{"th":"ความท้าทายคือทำให้วัสดุและกราฟิกสื่อความละเอียดประณีต พร้อมแยกกลิ่นได้ชัดและควบคุมต้นทุนเมื่อต่อยอดหลาย SKU\n\nความพรีเมียมเกิดจากการควบคุมองค์ประกอบมากกว่าปริมาณเอฟเฟกต์ ใช้เทคนิคพิเศษเฉพาะจุดที่ช่วยให้แบรนด์จดจำได้และไม่ทำให้ต้นทุนซับซ้อนเกินไป\n\nการทำให้สินค้าดูหรูด้วยสีทองและลายจำนวนมากอาจสร้างความประทับใจในภาพแรก แต่ถ้าทุกส่วนสะท้อนแสงพร้อมกัน ชื่อแบรนด์และชื่อกลิ่นจะไม่มีจุดเด่น เมื่อขยายกลิ่นเพิ่ม ค่าแม่พิมพ์และขั้นตอนพิเศษอาจเพิ่มตาม SKU ความท้าทายคือเลือกจุดที่การลงทุนด้านผิวสัมผัสสร้างความหมายจริง และทำให้สินค้าแตกต่างจากของขวัญทั่วไปโดยไม่เพิ่มความซับซ้อนเกินความจำเป็น","en":"If every element shines, the brand and scent lose focus. Special finishes may introduce setup and SKU costs; choose the locations where texture or reflection serves a meaningful role."}},{"step":"03","heading":{"th":"แนวคิดหลักและเหตุผลของอัตลักษณ์","en":"Creative Direction"},"body":{"th":"Quiet Craft — ให้จังหวะพื้นที่ว่างและผิวสัมผัสเป็นตัวเล่าเรื่อง ใช้จุดสะท้อนแสงเพียงเท่าที่มีหน้าที่\n\nSerif คลาสสิกและสัญลักษณ์เส้นเรียบสร้างความสมดุลกับพื้นฉลาก สีทองเป็น accent ไม่ใช่สีที่ต้องพิมพ์ทั่วทั้งงาน\n\nQuiet Craft ให้ความสำคัญกับความประณีตที่ไม่ต้องประกาศตัวเอง เลือกตัวอักษร Serif สงบ สีทองอุ่นเป็นจุดเน้น และพื้นขาวหรือสีอ่อนเพื่อให้วัสดุมีพื้นที่แสดงตัว โลโก้ไม่จำเป็นต้องใหญ่ที่สุดหากรูปทรง สัดส่วน และตำแหน่งทำให้เป็นจุดโฟกัสได้ ลายพฤกษศาสตร์สัมพันธ์กับประสบการณ์ของกลิ่น แต่ไม่ใช้ภาพแทนข้อมูลกลิ่นที่ยังไม่ยืนยัน","en":"Quiet Craft — calm serif typography, a light base and warm gold accents leave room for the material itself. Botanical imagery suggests the mood, not an unverified fragrance description."}},{"step":"04","heading":{"th":"Pattern, Mascot และระบบการใช้งาน","en":"Design Development"},"body":{"th":"พัฒนาลายเส้นพฤกษศาสตร์แบบละเอียดในฐานะกราฟิกประกอบของกลิ่น ให้ลายปรากฏเฉพาะขอบหรือมุมกล่องเพื่อรักษาพื้นที่ชื่อกลิ่น\n\nไม่ใช้ Mascot เพราะอารมณ์เงียบสงบและคุณภาพผิววัสดุเป็นจุดขายหลักของแนวทางนี้\n\nระบบฉลากใช้โลโก้และชื่อกลิ่นในตำแหน่งคงที่ แยกไฟล์ฟอยล์เฉพาะจุด และต่อยอดลายบนกล่องของขวัญและการ์ด\n\nออกแบบระบบที่คงตำแหน่งชื่อแบรนด์และชื่อกลิ่น ใช้ลายเส้นเฉพาะบริเวณขอบให้เกิดจังหวะเหมือนรายละเอียดบนงานคราฟต์ เมื่อเปลี่ยนกลิ่นให้เปลี่ยนชื่อและองค์ประกอบพฤกษศาสตร์บางส่วนในกริดเดิม แยกงาน Standard Collection ที่ใช้กราฟิกพิมพ์ปกติจาก Gift Edition ที่อาจเพิ่มฟอยล์เฉพาะจุด ไม่ใช้ Mascot เพราะจะเปลี่ยนน้ำเสียงจากความสงบไปเป็นบุคลิกตัวละคร ซึ่งไม่สอดคล้องกับทิศทางที่กำหนด","en":"Lock the brand and scent positions, vary names and selected botanical linework within a grid, and keep detailed patterns at edges. Consider standard printed editions and selective-foil gift editions. Avoid a mascot that would disrupt the quiet character."}},{"step":"05","heading":{"th":"จากแนวคิดสู่การผลิต","en":"Production Strategy"},"body":{"th":"เปรียบเทียบ Hot Foil กับฟอยล์ดิจิทัลตามจำนวนผลิตและวัสดุ แยกไฟล์ฟอยล์ออกจาก artwork และตรวจความหนาเส้นขั้นต่ำกับผู้ผลิต ทดสอบฉลากกับผิวกระปุกและอุณหภูมิใช้งานที่เกี่ยวข้อง\n\nเปรียบเทียบ Hot Foil กับ Digital Foil ตามจำนวนและวัสดุ เส้นลายละเอียดต้องไม่ต่ำกว่าข้อกำหนดเครื่องจริง และทดสอบการยึดเกาะบนผิวกระปุก\n\nวางตำแหน่งฟอยล์บนสัญลักษณ์หรือขอบที่ต้องการให้สะท้อนแสง แล้วเปรียบเทียบ Hot Foil และ Digital Foil โดยพิจารณาจำนวนผลิต วัสดุ ความคม และค่าเตรียมงาน แทนการตัดสินจากชื่อเทคนิค ตรวจว่าระยะเส้นและช่องไฟเหมาะกับข้อกำหนดของเครื่อง และว่าฉลากยึดเกาะบนผิวกระปุกในสภาพใช้งานจริงหรือไม่ สำหรับกล่องให้ตรวจแนวพับไม่ตัดตำแหน่งฟอยล์สำคัญ","en":"Compare hot foil and digital foil against real run length, stock, definition and setup costs. Verify minimum line and gap capabilities, adhesive on the jar and carton fold positions before selecting a finish."}},{"step":"06","heading":{"th":"การทดสอบและตรวจสอบ","en":"Quality Control"},"body":{"th":"ตรวจการเหลื่อมของฟอยล์ การหลุดลอก รอยพับ สีของฉลากกับกล่อง และความเหมาะสมของวัสดุกับความร้อน โดยต้องได้รับข้อมูลความปลอดภัยจากผู้ผลิตสินค้าก่อน\n\nตรวจการมองเห็นภายใต้แสงต่างกัน ความคมขอบฟอยล์ การเหลื่อม และการอ่านข้อมูลกลิ่น รวมถึงความทนของฉลากตามสภาพใช้งาน\n\nจัดตัวอย่างเปรียบเทียบแบบพิมพ์ปกติ แบบฟอยล์เฉพาะโลโก้ และแบบฟอยล์พร้อมรายละเอียดขอบ ตรวจภายใต้แสงหน้าร้านและแสงอุ่นในบ้าน รวมทั้งให้ผู้ทดสอบระบุชื่อกลิ่นโดยไม่ต้องหมุนกล่องหลายครั้ง ให้ผู้ผลิตตรวจรอยเหลื่อม การยึดติด และความคมของเทคนิคพิเศษ แล้วเทียบต้นทุนต่อชิ้นตามปริมาณจริงก่อนเลือกทางที่เหมาะสม","en":"Compare normal printing, logo-only foil and foil with edge details under retail and warm home lighting. Check scent-name legibility, registration, bonding and definition; compare actual per-unit costs."}},{"step":"07","heading":{"th":"คุณค่าที่คาดหวัง","en":"Concept Outcome"},"body":{"th":"ต้นแบบแสดงแนวทางตกแต่งพรีเมียมแบบเลือกเฉพาะจุด พร้อมเกณฑ์ตัดสินใจด้านวัสดุและต้นทุน ยังไม่มีการผลิตหรือวัดความคุ้มค่าจริง\n\nคุณค่าที่คาดหวังคือการสร้างภาพจำผ่านรายละเอียดที่สม่ำเสมอ และเปิดทางให้จัดระดับสินค้าได้โดยไม่ต้องรีแบรนด์ทั้งชุด ความพรีเมียมจะต้องได้รับการประเมินจากการรับรู้ของกลุ่มเป้าหมายและตัวอย่างวัสดุจริง ไม่ใช่จากการใส่ฟอยล์เพียงอย่างเดียว หากแบบธรรมดาสื่อสารคุณค่าได้ใกล้เคียงแบบพิเศษ อาจเก็บเทคนิคพิเศษไว้เฉพาะรุ่นของขวัญ","en":"Create an extensible collection with consistent detail and tiered finish options. If the standard proof communicates comparable value, reserve the special effect for gift editions. Premium perception remains a proposed test, not a result."}}],"storytelling":{"opening":"แบรนด์เทียนหอมสมมติต้องการให้กระปุกและกล่องสื่อถึงประสบการณ์การให้ของขวัญ แต่หากใช้สีทองและเทคนิคพิเศษเต็มพื้นที่ทุกชิ้น อาจดูหนักและเพิ่มต้นทุนโดยไม่สร้างจุดจดจำ","pain_point":"ความท้าทายคือทำให้วัสดุและกราฟิกสื่อความละเอียดประณีต พร้อมแยกกลิ่นได้ชัดและควบคุมต้นทุนเมื่อต่อยอดหลาย SKU","big_idea":"Quiet Craft — ให้จังหวะพื้นที่ว่างและผิวสัมผัสเป็นตัวเล่าเรื่อง ใช้จุดสะท้อนแสงเพียงเท่าที่มีหน้าที่","logo_rationale":"Serif คลาสสิกและสัญลักษณ์เส้นเรียบสร้างความสมดุลกับพื้นฉลาก สีทองเป็น accent ไม่ใช่สีที่ต้องพิมพ์ทั่วทั้งงาน","pattern_rationale":"พัฒนาลายเส้นพฤกษศาสตร์แบบละเอียดในฐานะกราฟิกประกอบของกลิ่น ให้ลายปรากฏเฉพาะขอบหรือมุมกล่องเพื่อรักษาพื้นที่ชื่อกลิ่น","mascot_rationale":"ไม่ใช้ Mascot เพราะอารมณ์เงียบสงบและคุณภาพผิววัสดุเป็นจุดขายหลักของแนวทางนี้","application_system":"ระบบฉลากใช้โลโก้และชื่อกลิ่นในตำแหน่งคงที่ แยกไฟล์ฟอยล์เฉพาะจุด และต่อยอดลายบนกล่องของขวัญและการ์ด","trade_off":"เปรียบเทียบ Hot Foil กับ Digital Foil ตามจำนวนและวัสดุ เส้นลายละเอียดต้องไม่ต่ำกว่าข้อกำหนดเครื่องจริง และทดสอบการยึดเกาะบนผิวกระปุก","validation_plan":"ตรวจการมองเห็นภายใต้แสงต่างกัน ความคมขอบฟอยล์ การเหลื่อม และการอ่านข้อมูลกลิ่น รวมถึงความทนของฉลากตามสภาพใช้งาน","visual_asset_brief":["Logo และ botanical line motif","Foil separation diagram","Jar and gift box mockup","Macro ฟอยล์กับพื้นผิว","Finish comparison sample concept"]},"deliverables":["Premium identity concept","Foil placement direction","Label & box visual","Finishing sample checklist"],"assetNotes":"โลโก้เวกเตอร์ต้นแบบสร้างแยกจากภาพจำลอง อาจมีรายละเอียดไม่ตรงกับโลโก้ใน Mockup ทุกจุด; ภาพ hero และ card มาจากภาพเดียวกัน ไม่ใช่ภาพถ่ายจริง; ชื่อแบรนด์ยังไม่ได้ตรวจสอบสิทธิ์เครื่องหมายการค้า","featured":false},{"brand":"TECHMATE","title":"ออกแบบพื้นที่นิทรรศการให้สื่อสารบริการได้ในเวลาอันสั้น","summary":"สร้างระบบกราฟิกบูธที่อ่านง่ายจากระยะไกล เชื่อมกับพื้นที่สาธิตสินค้าและขั้นตอนติดตั้ง","headline":{"th":"จากพื้นที่บูธที่เต็มไปด้วยข้อความ สู่ประสบการณ์ที่เข้าใจได้ตามระยะการมอง","en":"Turn a crowded exhibition booth into a clear journey across viewing distances."},"timeline":[{"step":"01","heading":{"th":"จุดเริ่มต้นและบริบท","en":"Project Brief"},"body":{"th":"ในงานแสดงสินค้าสมมติ TECHMATE มีบริการหลายประเภทที่ต้องสื่อสารพร้อมกัน แต่ผู้ชมไม่จำเป็นต้องเริ่มจากจุดเดียวกัน และอาจเดินผ่านโดยไม่หยุด การออกแบบจึงต้องคิดจากเส้นทางและเวลาที่ผู้ชมให้กับบูธ\n\nแบรนด์เทคโนโลยีสมมติเตรียมออกงานแสดงสินค้าและต้องสื่อสารบริการหลายประเภทในพื้นที่จำกัด โดยผู้เข้าชมเดินผ่านเร็วและมีจุดสาธิตที่ต้องเข้าถึงง่าย\n\nTECHMATE เป็นโจทย์สมมติของผู้ให้บริการเทคโนโลยีที่ต้องนำเสนอหลายโซลูชันในพื้นที่จัดแสดงเดียว ผู้ชมบางคนรู้จักชื่อบริษัทอยู่แล้ว แต่บางคนเดินผ่านโดยไม่มีข้อมูลมาก่อน จึงต้องออกแบบให้คนที่เข้าจากต่างทิศทางสามารถเข้าใจข้อเสนอหลักได้ ก่อนเลือกว่าจะหยุดดูการสาธิตหรือเดินเข้าไปพูดคุยกับทีมงาน","en":"A hypothetical technology provider needs to communicate several solutions to visitors approaching from different directions. The booth should help them decide whether to stop, see a demonstration or speak to the team."}},{"step":"02","heading":{"th":"Pain Point และเหตุผลที่ต้องเปลี่ยน","en":"Insight"},"body":{"th":"ถ้าทุกป้ายใช้ขนาดข้อความเท่ากัน ผู้ชมอาจไม่รู้ว่าบริษัททำอะไรและควรเข้าโซนใด การตกแต่งที่บดบังทางเดินหรือจุดสาธิตยังลดประโยชน์ของพื้นที่\n\nบูธที่มีข้อความมากเกินไปมักสื่อสารช้า ควรแบ่งกราฟิกตามระยะมองเห็น: แบรนด์จากไกล หมวดบริการจากระยะกลาง และรายละเอียดจากระยะใกล้\n\nเมื่อทุกบริการถูกนำขึ้นป้ายพร้อมคำอธิบายยาว ๆ บูธอาจดูมีข้อมูลครบจากมุมผู้จัด แต่สำหรับผู้ชมที่กำลังเดินผ่านจะไม่มีข้อความหลักที่ชวนให้หยุด การใช้กราฟิกใหญ่โดยไม่คิดพื้นที่สาธิตอาจทำให้คนรวมตัวในจุดที่กีดขวางการสัญจร ปัญหาจึงเป็นทั้ง Information Design และประสบการณ์เชิงพื้นที่ ไม่ใช่แค่การออกแบบ Backdrop ให้สวย","en":"Dense service descriptions can bury the main message, and poorly positioned graphics can conflict with circulation. Treat the project as both information design and spatial experience."}},{"step":"03","heading":{"th":"แนวคิดหลักและเหตุผลของอัตลักษณ์","en":"Creative Direction"},"body":{"th":"Clear Connection — ทำให้ข้อมูลเชื่อมต่อกันจากระยะไกลสู่ระยะใกล้ ผ่านลำดับภาพและสัญญาณนำทาง\n\nwordmark และสี Navy/ส้มใช้เป็นจุดสังเกตจากทางเดิน ส่วนตัวอักษรบริการต้องคงความอ่านง่ายไม่พึ่งเอฟเฟกต์เทคโนโลยีมากเกินไป\n\nClear Connection ใช้แนวคิดการเชื่อมต่อเป็นภาษาที่พาคนจากภาพรวมไปยังรายละเอียด ตัวอักษรชื่อแบรนด์และสี Navy เป็นหลักยึด ส่วนสีส้มใช้ชี้จุดสำคัญหรือแบ่งโซนอย่างมีหน้าที่ รูปทรงกราฟิกที่เคลื่อนไปในทิศทางเดียวกันช่วยสร้างความต่อเนื่อง ไม่ใช้เอฟเฟกต์เทคโนโลยีที่ทำให้ข้อความอ่านยาก เป้าหมายคือความเข้าใจง่ายก่อนความหวือหวา","en":"Clear Connection — navy provides the anchor and orange highlights key zones. Directional lines guide visitors from broad identification to detail without decorative effects that reduce readability."}},{"step":"04","heading":{"th":"Pattern, Mascot และระบบการใช้งาน","en":"Design Development"},"body":{"th":"ใช้แถบกราฟิกและแนวเส้นเชื่อมเป็น directional motif นำสายตาไปสู่แต่ละโซน ไม่ใช้ลายหนาแน่นหลังข้อความหรือหน้าจอ\n\nไม่สร้าง Mascot เพราะโครงการนี้เน้นความชัดเจนของข้อมูล B2B และการสาธิต หากต้องการตัวช่วยสื่อสารอาจใช้ icon system แทน\n\nแบ่งป้ายระดับบนสำหรับแบรนด์ ระดับกลางสำหรับหมวดบริการ และระยะใกล้สำหรับรายละเอียด เชื่อม Key Visual ไปยัง counter, backdrop และสื่อแจก\n\nแบ่งการสื่อสารออกเป็นสามชั้น: ระยะไกลให้รู้ชื่อและหมวดบริการ ระยะกลางให้เลือกโซลูชันที่สนใจ ระยะใกล้ให้ดูรายละเอียดและการสาธิต กราฟิกเส้นเชื่อมสามารถต่อจากป้ายบนไปถึงเคาน์เตอร์ แต่ต้องหยุดหรือเบาลงเมื่ออยู่หลังข้อความและจอภาพ ใช้ icon system สำหรับจำแนกบริการแทน Mascot เพราะผู้ชม B2B ต้องการเข้าใจข้อเสนอและหลักฐานประกอบมากกว่าตัวละครที่ไม่มีหน้าที่ชัด","en":"Create three information layers: brand and service category from far away, solution choice at medium distance, and details and demos close up. Use a coherent icon system rather than a mascot for B2B navigation; keep directional motifs away from dense copy and screens."}},{"step":"05","heading":{"th":"จากแนวคิดสู่การผลิต","en":"Production Strategy"},"body":{"th":"กำหนดไฟล์ตามขนาดหน้างานจริง เลือกวัสดุกราฟิกตามระบบโครงสร้างและข้อกำหนดสถานที่ ตรวจรอยต่อแผ่น แนวติดตั้ง และการถอดประกอบร่วมกับผู้รับเหมาบูธ\n\nกราฟิกต่อเนื่องต้องเผื่อรอยต่อและการประกอบจริง วัสดุและโครงสร้างต้องเป็นไปตามข้อกำหนดสถานที่ ไม่สรุปว่าติดตั้งได้จากภาพ render เพียงอย่างเดียว\n\nสร้าง artwork map จากขนาดแผงและโครงสร้างที่ผู้รับเหมารับรอง แยกกราฟิกตามชิ้นส่วนที่ต้องผลิตและติดตั้ง ระบุรอยต่อและจุดที่อาจถูกอุปกรณ์บัง เปรียบเทียบวัสดุพิมพ์สำหรับแผงทึบ ผ้าหรือฟิล์มตามวิธีประกอบและข้อกำหนดสถานที่ วางแผนเปลี่ยนข้อความเฉพาะโซนที่มีการอัปเดตบ่อยโดยไม่จำเป็นต้องผลิตฉากทั้งหมดใหม่","en":"Obtain approved panel and structure dimensions from the contractor. Map artwork to panels, seams and obstructions; compare rigid, fabric or film options against assembly and venue rules. Separate frequently updated graphics where possible."}},{"step":"06","heading":{"th":"การทดสอบและตรวจสอบ","en":"Quality Control"},"body":{"th":"ตรวจขนาดจริง มุมมอง ป้ายทางเข้า การไม่ปิดทางเดิน และความปลอดภัยของโครงสร้างโดยผู้รับผิดชอบหน้างาน ตรวจ proof สีและรายการชิ้นงานก่อนติดตั้ง\n\nทดสอบการอ่านจากมุมทางเดินและความสูงสายตา ตรวจพื้นที่สาธิต การสัญจรและการเข้าถึงร่วมกับผู้รับเหมาบูธก่อนอนุมัติ\n\nทดสอบการมองจากแนวทางเดินตามตำแหน่งบูธที่เสนอ ให้คนที่ไม่รู้จักแบรนด์ลองบอกว่าบริษัททำอะไรและควรไปจุดไหน จากนั้นตรวจแบบกับผู้รับเหมาเรื่องรอยต่อ การประกอบ ระยะเข้าถึงอุปกรณ์ และข้อกำหนดความปลอดภัยของสถานที่ ตรวจปรู๊ฟกราฟิกขนาดจริงในจุดที่มีข้อความเล็กก่อนเข้าสู่การผลิตทั้งชุด","en":"Test the proposed sightlines with people unfamiliar with the brand. Confirm panel joints, installation, access and venue safety requirements with contractors and inspect actual-size proofs for small text."}},{"step":"07","heading":{"th":"คุณค่าที่คาดหวัง","en":"Concept Outcome"},"body":{"th":"แนวคิดแสดงระบบภาพนิทรรศการที่เชื่อมการสื่อสารกับพื้นที่ใช้งาน พร้อมขั้นตอนตรวจไฟล์และติดตั้ง ยังไม่มีงานแสดงสินค้าหรือจำนวนผู้เข้าชมจริง\n\nแนวคิดนี้ต้องการให้บูธทำหน้าที่เป็นลำดับบทสนทนา ตั้งแต่เห็นชื่อ เข้าใจบริการ ไปจนถึงสนทนากับผู้เชี่ยวชาญ เมื่อมีงานจริงจึงประเมินจากความเข้าใจของผู้ชม การใช้งานพื้นที่ และข้อเสนอแนะทีมสาธิต ไม่สร้างตัวเลขจำนวนผู้เข้าชมหรือ Lead ที่ไม่มีหลักฐาน ระบบกราฟิกแบบแบ่งชิ้นยังมีโอกาสต่อยอดสู่งานแสดงสินค้าขนาดอื่นโดยปรับตามพื้นที่จริง","en":"The proposed booth acts as a sequence of conversations from awareness to consultation. Evaluate comprehension, circulation and demo-team feedback at a real event; no visitor or lead figures are claimed."}}],"storytelling":{"opening":"ในงานแสดงสินค้าสมมติ TECHMATE มีบริการหลายประเภทที่ต้องสื่อสารพร้อมกัน แต่ผู้ชมไม่จำเป็นต้องเริ่มจากจุดเดียวกัน และอาจเดินผ่านโดยไม่หยุด การออกแบบจึงต้องคิดจากเส้นทางและเวลาที่ผู้ชมให้กับบูธ","pain_point":"ถ้าทุกป้ายใช้ขนาดข้อความเท่ากัน ผู้ชมอาจไม่รู้ว่าบริษัททำอะไรและควรเข้าโซนใด การตกแต่งที่บดบังทางเดินหรือจุดสาธิตยังลดประโยชน์ของพื้นที่","big_idea":"Clear Connection — ทำให้ข้อมูลเชื่อมต่อกันจากระยะไกลสู่ระยะใกล้ ผ่านลำดับภาพและสัญญาณนำทาง","logo_rationale":"wordmark และสี Navy/ส้มใช้เป็นจุดสังเกตจากทางเดิน ส่วนตัวอักษรบริการต้องคงความอ่านง่ายไม่พึ่งเอฟเฟกต์เทคโนโลยีมากเกินไป","pattern_rationale":"ใช้แถบกราฟิกและแนวเส้นเชื่อมเป็น directional motif นำสายตาไปสู่แต่ละโซน ไม่ใช้ลายหนาแน่นหลังข้อความหรือหน้าจอ","mascot_rationale":"ไม่สร้าง Mascot เพราะโครงการนี้เน้นความชัดเจนของข้อมูล B2B และการสาธิต หากต้องการตัวช่วยสื่อสารอาจใช้ icon system แทน","application_system":"แบ่งป้ายระดับบนสำหรับแบรนด์ ระดับกลางสำหรับหมวดบริการ และระยะใกล้สำหรับรายละเอียด เชื่อม Key Visual ไปยัง counter, backdrop และสื่อแจก","trade_off":"กราฟิกต่อเนื่องต้องเผื่อรอยต่อและการประกอบจริง วัสดุและโครงสร้างต้องเป็นไปตามข้อกำหนดสถานที่ ไม่สรุปว่าติดตั้งได้จากภาพ render เพียงอย่างเดียว","validation_plan":"ทดสอบการอ่านจากมุมทางเดินและความสูงสายตา ตรวจพื้นที่สาธิต การสัญจรและการเข้าถึงร่วมกับผู้รับเหมาบูธก่อนอนุมัติ","visual_asset_brief":["Logo และ directional motif","Visitor journey diagram","Sign hierarchy diagram","Booth concept render","Counter และ backdrop detail"]},"deliverables":["Exhibition graphics concept","Visual hierarchy","Signage asset list","Installation & safety checklist"],"assetNotes":"โลโก้เวกเตอร์ต้นแบบสร้างแยกจากภาพจำลอง อาจมีรายละเอียดไม่ตรงกับโลโก้ใน Mockup ทุกจุด; ภาพ hero และ card มาจากภาพเดียวกัน ไม่ใช่ภาพถ่ายจริง; ชื่อแบรนด์ยังไม่ได้ตรวจสอบสิทธิ์เครื่องหมายการค้า","featured":false},{"brand":"ECOLABEL","title":"ออกแบบฉลากโดยคำนึงถึงกระบวนการคัดแยกและรีไซเคิล","summary":"ศึกษาแนวทางเลือกโครงสร้างฉลากและกาวที่เหมาะกับบรรจุภัณฑ์ โดยต้องผ่านการทดสอบก่อนกล่าวอ้างด้านสิ่งแวดล้อม","headline":{"th":"ฉลากที่คิดถึงชีวิตหลังการใช้งาน ไม่ใช่เพียงภาพลักษณ์สีเขียว","en":"Consider the label after use, not just a green-looking identity."},"timeline":[{"step":"01","heading":{"th":"จุดเริ่มต้นและบริบท","en":"Project Brief"},"body":{"th":"โจทย์สมมติของ ECOLABEL เริ่มเมื่อแบรนด์ต้องการปรับบรรจุภัณฑ์ให้พิจารณาขั้นตอนหลังการใช้งานด้วย แต่การเปลี่ยนสีฉลากเป็นเขียวหรือใส่รูปใบไม้ไม่ได้ตอบคำถามว่าวัสดุจะเข้ากับระบบคัดแยกและรีไซเคิลหรือไม่\n\nโจทย์สมมติด้านฉลากสำหรับบรรจุภัณฑ์ที่ต้องการพิจารณาการจัดการหลังใช้งาน คำถามหลักไม่ใช่ว่าฉลากดูเป็นมิตรต่อสิ่งแวดล้อมหรือไม่ แต่โครงสร้างวัสดุและกาวเข้ากับเส้นทางรีไซเคิลที่เกี่ยวข้องหรือไม่\n\nECOLABEL ตั้งต้นจากโจทย์ที่แบรนด์ต้องการพิจารณาบรรจุภัณฑ์ตั้งแต่ก่อนใช้งานจนถึงหลังการทิ้ง ฉลากเป็นชิ้นส่วนเล็กแต่สัมพันธ์กับชนิดภาชนะ กาว ฟิล์ม และกระบวนการจัดการวัสดุปลายทาง โครงการจึงไม่ได้เริ่มจากคำถามว่าจะทำให้ดูรักษ์โลกอย่างไร แต่เริ่มจากข้อมูลใดที่ต้องรู้ก่อนตัดสินใจเลือกวัสดุและสื่อสารกับผู้บริโภค","en":"ECOLABEL explores the relationship between the container, label, adhesive, ink and downstream material handling. Start with the information needed to evaluate material choices rather than the appearance of environmental responsibility."}},{"step":"02","heading":{"th":"Pain Point และเหตุผลที่ต้องเปลี่ยน","en":"Insight"},"body":{"th":"ชนิดภาชนะ ฟิล์ม กาว และระบบรีไซเคิลมีผลต่อความเข้ากันได้ การใช้คำกล่าวอ้างก่อนมีหลักฐานเสี่ยงสร้างความเข้าใจผิดและลดความน่าเชื่อถือ\n\nการใช้ภาพใบไม้หรือสัญลักษณ์รีไซเคิลไม่ได้ยืนยันคุณสมบัติวัสดุ จำเป็นต้องเริ่มจากชนิดภาชนะ ระบบคัดแยก และข้อกำหนดของผู้รับรีไซเคิลก่อนเลือกวัสดุ\n\nภาพใบไม้และสีเขียวสามารถสร้างความรู้สึกเกี่ยวกับธรรมชาติได้ แต่ไม่ได้ยืนยันว่าฉลากสามารถแยกออกหรือเข้ากับกระบวนการรีไซเคิลได้ หากเปลี่ยนไปใช้กาวที่ลอกง่ายแต่ไม่เหมาะกับสภาพแช่เย็น ฉลากอาจไม่ตอบโจทย์ระหว่างใช้งาน ในทางกลับกัน กาวที่ยึดเกาะดีอาจไม่ตรงกับระบบปลายทางบางประเภท ปัญหานี้ต้องแก้จากสมรรถนะและหลักฐาน ไม่ใช่จากการออกแบบภาพลักษณ์เพียงอย่างเดียว","en":"Green imagery does not establish recyclability. An easy-release adhesive may fail during use while strong bonding may conflict with a particular recovery process. The problem requires performance evidence across the intended lifecycle."}},{"step":"03","heading":{"th":"แนวคิดหลักและเหตุผลของอัตลักษณ์","en":"Creative Direction"},"body":{"th":"Design for the Next Cycle — ใช้กราฟิกช่วยอธิบายข้อมูลที่ตรวจสอบได้ และวางการทดสอบวัสดุเป็นส่วนหนึ่งของโจทย์ออกแบบ\n\nสัญลักษณ์พฤกษศาสตร์และสีเขียวใช้สื่อธีมการศึกษาเท่านั้น ไม่ใช่ตรารับรอง จัดชื่อและข้อความให้แยกจากเครื่องหมายรับรองอย่างชัดเจน\n\nDesign for the Next Cycle เลือกภาษาภาพที่อธิบายความต่อเนื่องของวัสดุโดยใช้เส้นโค้งและโมดูลเชื่อมต่ออย่างเป็นนามธรรม สีเขียวทำหน้าที่เป็นธีมของโครงการศึกษา ไม่ใช่ตรารับรอง จัด Typography ให้แยกชื่อแบรนด์ ข้อมูลวัสดุ และคำแนะนำที่ได้รับการตรวจสอบออกจากกันอย่างชัดเจน เพื่อไม่ให้ผู้ซื้อสับสนว่ากราฟิกคือหลักฐานรับรอง","en":"Design for the Next Cycle — abstract connected modules express the study theme. Separate brand identity, material information and verified instructions; green colour and botanical marks are not certifications."}},{"step":"04","heading":{"th":"Pattern, Mascot และระบบการใช้งาน","en":"Design Development"},"body":{"th":"ใช้เส้นโค้งวนหรือโมดูลเชื่อมต่อเป็นลายประกอบแนวคิดวงจรวัสดุ โดยไม่เลียนแบบเครื่องหมายรับรองหรือใช้แทนคำแนะนำการทิ้งที่ยืนยันแล้ว\n\nไม่ใช้ Mascot เพราะโจทย์ต้องเน้นความชัดเจนของข้อมูลวัสดุและหลักฐาน มากกว่าการใช้ตัวละครโน้มน้าวด้านสิ่งแวดล้อม\n\nกำหนดพื้นที่ข้อมูลชนิดวัสดุและคำแนะนำแยกส่วนสำหรับใช้เมื่อได้รับข้อมูลยืนยัน พิจารณาทางเลือก wash-off เฉพาะระบบที่รองรับ และแยกการสื่อสารออกจากผลการทดสอบ\n\nลายต่อเนื่องที่สื่อถึงวงจรใช้เป็นกราฟิกรองได้ แต่ไม่ควรออกแบบให้คล้ายสัญลักษณ์รับรองหรือใช้แทนคำอธิบายการทิ้ง แม่แบบฉลากต้องสำรองพื้นที่สำหรับข้อมูลชนิดวัสดุและคำแนะนำที่ผ่านการตรวจสอบในอนาคต โดยไม่ต้องรื้ออัตลักษณ์ใหม่ทั้งหมด ไม่ใช้ Mascot เพราะการโน้มน้าวด้วยตัวละครอาจดึงความสนใจออกจากข้อเท็จจริงที่ต้องอ่าน ภาพ Mockup เดิมที่มีคำและสัญลักษณ์รีไซเคิลควรถูกแทนที่ด้วยภาพที่ไม่กล่าวอ้างก่อนเผยแพร่จริง","en":"Use a supporting cyclic motif without imitating certification symbols. Reserve space for validated disposal instructions. Avoid a persuasive mascot; replace the original mockup bearing unverified recycling claims before public display."}},{"step":"05","heading":{"th":"จากแนวคิดสู่การผลิต","en":"Production Strategy"},"body":{"th":"เปรียบเทียบชนิดฟิล์มหรือกระดาษ กาวที่เหมาะกับภาชนะ และทางเลือก wash-off เมื่อมีระบบรองรับ ขอข้อมูล supplier และทดสอบการแยกออกในกระบวนการที่กำหนดร่วมกับผู้เชี่ยวชาญวัสดุ\n\nฉลากที่ลอกออกง่ายในบางเงื่อนไขไม่ได้แปลว่าใช้ได้กับทุกกระบวนการ ต้องพิจารณากาว ภาชนะและเงื่อนไขผู้รับรีไซเคิลจริง ภาพ mockup เดิมมีสัญลักษณ์/คำเกี่ยวกับรีไซเคิลที่ยังไม่ยืนยัน จึงต้องเปลี่ยนภาพก่อนเผยแพร่\n\nการศึกษาควรเริ่มจากระบุวัสดุภาชนะ รูปแบบฉลาก กาว หมึก และเงื่อนไขผู้รับรีไซเคิลเป้าหมาย แล้วจึงขอข้อมูลทางเทคนิคจาก Supplier เพื่อเลือกตัวอย่างเปรียบเทียบ ฉลาก Wash-off เป็นทางเลือกที่ต้องประเมินภายใต้กระบวนการที่เกี่ยวข้อง ไม่ใช่คำตอบเดียวสำหรับทุกภาชนะ ให้ความสำคัญกับความทนขณะใช้งานด้วย เพราะฉลากที่สูญเสียข้อมูลหรือหลุดก่อนหมดอายุใช้งานไม่ถือว่าตอบโจทย์ครบ","en":"Identify the actual container, label, adhesive, ink and intended recovery system. Ask suppliers for technical evidence and compare wash-off options within relevant process conditions; retain label durability during normal use."}},{"step":"06","heading":{"th":"การทดสอบและตรวจสอบ","en":"Quality Control"},"body":{"th":"ตรวจคุณสมบัติระหว่างการใช้งานและหลังใช้งานตามวิธีทดสอบที่เกี่ยวข้อง รวมถึงผลกระทบของหมึก กาว และฟิล์มต่อกระบวนการจริง ตรวจคำกล่าวอ้างก่อนเผยแพร่\n\nขอข้อมูลวัสดุจาก supplier และข้อกำหนดผู้รับรีไซเคิล ทดสอบการแยกและการใช้งานตามวิธีที่เกี่ยวข้อง ก่อนอนุมัติข้อความสื่อสาร\n\nแยกการทดสอบเป็นความเหมาะสมในระหว่างใช้งานและความเข้ากันได้กับกระบวนการปลายทาง ให้ผู้ผลิตหรือผู้เชี่ยวชาญที่เกี่ยวข้องกำหนดวิธีและเงื่อนไขประเมินที่เหมาะกับวัสดุจริง บันทึกขอบเขตผลทดสอบอย่างชัดเจน และทบทวนข้อความบนฉลากให้ตรงกับหลักฐานที่มี หากยังไม่มีข้อมูลยืนยัน ให้คงเนื้อหาเป็นแนวทางการศึกษาโดยไม่ใช้คำรับรองเชิงสิ่งแวดล้อม","en":"Assess in-use performance and downstream compatibility separately with the relevant producers or specialists. Record test scope and limitations and allow only claims supported by the evidence."}},{"step":"07","heading":{"th":"คุณค่าที่คาดหวัง","en":"Concept Outcome"},"body":{"th":"ผลลัพธ์ในระดับแนวคิดคือแผนการเลือกวัสดุและทดสอบที่ใช้เป็นจุดเริ่มต้นของการพัฒนาฉลาก ไม่ใช่การรับรองว่ารีไซเคิลได้ ภาพจำลองมีข้อความเชิงรีไซเคิลซึ่งยังไม่ได้รับการพิสูจน์\n\nคุณค่าของแนวคิดนี้คือการเชื่อมกระบวนการเลือกวัสดุเข้ากับการออกแบบข้อมูล ช่วยให้ทีมรู้ว่าคำสื่อสารใดใช้ได้และเรื่องใดยังต้องพิสูจน์ การนำไปผลิตควรเริ่มจากชุดทดลองวัสดุที่มีขอบเขตชัดเจน เมื่อมีหลักฐานจริงจึงค่อยอนุมัติข้อความและขยายระบบไปยังบรรจุภัณฑ์อื่น ไม่มีการอ้างว่าลดคาร์บอนหรือรีไซเคิลได้จากภาพจำลองนี้","en":"The proposed value is a framework linking material decisions to responsible information design. Start with bounded material trials and approve claims only after validation; no carbon reduction or recyclability is claimed."}}],"storytelling":{"opening":"โจทย์สมมติของ ECOLABEL เริ่มเมื่อแบรนด์ต้องการปรับบรรจุภัณฑ์ให้พิจารณาขั้นตอนหลังการใช้งานด้วย แต่การเปลี่ยนสีฉลากเป็นเขียวหรือใส่รูปใบไม้ไม่ได้ตอบคำถามว่าวัสดุจะเข้ากับระบบคัดแยกและรีไซเคิลหรือไม่","pain_point":"ชนิดภาชนะ ฟิล์ม กาว และระบบรีไซเคิลมีผลต่อความเข้ากันได้ การใช้คำกล่าวอ้างก่อนมีหลักฐานเสี่ยงสร้างความเข้าใจผิดและลดความน่าเชื่อถือ","big_idea":"Design for the Next Cycle — ใช้กราฟิกช่วยอธิบายข้อมูลที่ตรวจสอบได้ และวางการทดสอบวัสดุเป็นส่วนหนึ่งของโจทย์ออกแบบ","logo_rationale":"สัญลักษณ์พฤกษศาสตร์และสีเขียวใช้สื่อธีมการศึกษาเท่านั้น ไม่ใช่ตรารับรอง จัดชื่อและข้อความให้แยกจากเครื่องหมายรับรองอย่างชัดเจน","pattern_rationale":"ใช้เส้นโค้งวนหรือโมดูลเชื่อมต่อเป็นลายประกอบแนวคิดวงจรวัสดุ โดยไม่เลียนแบบเครื่องหมายรับรองหรือใช้แทนคำแนะนำการทิ้งที่ยืนยันแล้ว","mascot_rationale":"ไม่ใช้ Mascot เพราะโจทย์ต้องเน้นความชัดเจนของข้อมูลวัสดุและหลักฐาน มากกว่าการใช้ตัวละครโน้มน้าวด้านสิ่งแวดล้อม","application_system":"กำหนดพื้นที่ข้อมูลชนิดวัสดุและคำแนะนำแยกส่วนสำหรับใช้เมื่อได้รับข้อมูลยืนยัน พิจารณาทางเลือก wash-off เฉพาะระบบที่รองรับ และแยกการสื่อสารออกจากผลการทดสอบ","trade_off":"ฉลากที่ลอกออกง่ายในบางเงื่อนไขไม่ได้แปลว่าใช้ได้กับทุกกระบวนการ ต้องพิจารณากาว ภาชนะและเงื่อนไขผู้รับรีไซเคิลจริง ภาพ mockup เดิมมีสัญลักษณ์/คำเกี่ยวกับรีไซเคิลที่ยังไม่ยืนยัน จึงต้องเปลี่ยนภาพก่อนเผยแพร่","validation_plan":"ขอข้อมูลวัสดุจาก supplier และข้อกำหนดผู้รับรีไซเคิล ทดสอบการแยกและการใช้งานตามวิธีที่เกี่ยวข้อง ก่อนอนุมัติข้อความสื่อสาร","visual_asset_brief":["Neutral label identity (no certification mark)","Cycle motif concept","Material comparison diagram","Proposed separation test diagram","Revised bottle mockup without environmental claims"]},"deliverables":["Label identity concept","Material compatibility study plan","Wash-off evaluation checklist","Environmental claim review"],"assetNotes":"โลโก้เวกเตอร์ต้นแบบสร้างแยกจากภาพจำลอง อาจมีรายละเอียดไม่ตรงกับโลโก้ใน Mockup ทุกจุด; ภาพ hero และ card มาจากภาพเดียวกัน ไม่ใช่ภาพถ่ายจริง; ชื่อแบรนด์ยังไม่ได้ตรวจสอบสิทธิ์เครื่องหมายการค้า; ไม่ควรใช้ข้อความในภาพเกี่ยวกับการรีไซเคิลเป็นคำกล่าวอ้างจริงหรือเครื่องหมายรับรอง","featured":false},{"brand":"CITRUS","title":"เปลี่ยนงานออกแบบให้เป็นไฟล์พร้อมเข้าสู่กระบวนการพิมพ์","summary":"วางขั้นตอนตรวจ Artwork และ Prepress สำหรับฉลากเครื่องดื่ม ตั้งแต่โครงสร้างไฟล์จนถึงการอนุมัติ Proof","headline":{"th":"ไฟล์ที่สวยบนหน้าจอ ต้องยังคงความถูกต้องเมื่อเข้าสู่เครื่องพิมพ์","en":"Artwork that looks right on screen must remain correct on press."},"timeline":[{"step":"01","heading":{"th":"จุดเริ่มต้นและบริบท","en":"Project Brief"},"body":{"th":"CITRUS เป็นโจทย์จำลองการเตรียมงานฉลากเครื่องดื่ม เมื่อมีรสชาติใหม่และขนาดขวดหลายแบบ งานที่ดูคล้ายกันอาจถูกส่งข้ามเวอร์ชันได้ง่าย จึงต้องคิดถึงคนที่รับไฟล์ต่อและวิธีอนุมัติตั้งแต่ต้น\n\nโจทย์จำลองของผู้ผลิตฉลากเครื่องดื่มที่มี artwork หลายรสชาติและหลายขนาด ต้องการลดความเสี่ยงที่เกิดจากไฟล์ผิดเวอร์ชัน ขนาดผิด หรือข้อมูลพิมพ์ไม่ครบก่อนส่งโรงงาน\n\nCITRUS เป็นกรณีศึกษาสมมติที่เริ่มหลังจากแบรนด์มีทิศทางภาพลักษณ์อยู่แล้วและต้องนำไปใช้กับฉลากหลายขนาด ในมุมของทีมออกแบบ งานดูเสร็จเมื่อภาพบนจอตรงกับแนวคิด แต่ในมุมโรงงานยังต้องตอบคำถามเกี่ยวกับขนาดจริง สี หมึกพิเศษ เส้นตัด และข้อมูลฉบับอนุมัติ โครงการนี้จึงเน้นช่วงรอยต่อระหว่าง Design กับ Production ซึ่งมีผลต่อความถูกต้องของงานมากกว่าการเพิ่มความสวยให้ Mockup","en":"CITRUS starts with an existing beverage identity and multiple label sizes. The brief concerns the transition from design approval to production, where dimensions, inks, cut paths and approved copy must be explicit."}},{"step":"02","heading":{"th":"Pain Point และเหตุผลที่ต้องเปลี่ยน","en":"Insight"},"body":{"th":"ไฟล์ผิดขนาด ข้อมูลไม่ครบ หรือสีพิเศษไม่แยกจากกราฟิก อาจทำให้เกิดการแก้ไขซ้ำหรือผลิตผิด ความเสี่ยงเพิ่มขึ้นเมื่อมีหลาย SKU และผู้เกี่ยวข้องหลายฝ่าย\n\nไฟล์ที่ดูดีบนหน้าจอไม่ได้แปลว่าพร้อมพิมพ์ งาน Prepress ต้องเชื่อมการออกแบบเข้ากับสเปกเครื่อง วัสดุ หมึก ระบบตัด และขั้นตอนอนุมัติอย่างเป็นระบบ\n\nความผิดพลาดอาจเกิดจากไฟล์ชื่อคล้ายกัน เช่น ฉลากขนาดเล็กและขนาดใหญ่ถูกส่งผิด หรือกราฟิกที่ดูถูกต้องบนจอมีรายละเอียดหลุดออกจากพื้นที่ปลอดภัย การแก้สีที่ไม่บันทึก Revision ยังทำให้ฝ่ายผลิตไม่ทราบว่าต้องยึด Proof ใด ปัญหาหลักคือไม่มีระบบตรวจสอบและความรับผิดชอบร่วมกัน ไม่ใช่การขาดความคิดสร้างสรรค์","en":"Similar filenames, misplaced safe-area elements and undocumented colour revisions can lead to the wrong artwork being printed. The issue is traceability and shared responsibility rather than a lack of creativity."}},{"step":"03","heading":{"th":"แนวคิดหลักและเหตุผลของอัตลักษณ์","en":"Creative Direction"},"body":{"th":"From Artwork to Print — ใช้ระบบการจัดการไฟล์ที่รักษาเจตนาการออกแบบและตรวจสอบย้อนกลับได้\n\nคงตำแหน่ง wordmark และองค์ประกอบส้มเป็น master brand asset ไม่ออกแบบโลโก้ใหม่เพื่อความต่างโดยไม่จำเป็น ตรวจขนาดและสีตามสเปกที่อนุมัติ\n\nFrom Artwork to Print ให้ความสำคัญกับการรักษาเจตนาของงานออกแบบระหว่างส่งต่อ โดยไม่เปลี่ยนโลโก้หรือบุคลิกเดิมเพียงเพื่อให้ดูเหมือนเป็นโครงการรีแบรนด์ใหม่ กำหนดตำแหน่งชื่อ CITRUS และสัญลักษณ์ผลส้มเป็น Master Asset ที่อ้างอิงได้ ส่วนกราฟิกผลไม้และแถบสีรองสามารถปรับตามสูตรในขอบเขตที่อนุมัติ ตัวอักษรข้อมูลผลิตภัณฑ์ต้องพิจารณาจากการอ่านบนฉลากจริง ไม่ใช่ขนาดที่เห็นเมื่อซูมบนหน้าจอ","en":"From Artwork to Print — preserve the citrus wordmark and orange mark as master assets. Allow approved fruit graphics and accent colours to change within the established system. Review type on the real label, not just at screen zoom."}},{"step":"04","heading":{"th":"Pattern, Mascot และระบบการใช้งาน","en":"Design Development"},"body":{"th":"ใช้กราฟิกผลไม้เป็น secondary asset ที่มีกรอบและระยะปลอดภัยชัดเจน แยกจากข้อมูลสำคัญและเส้นตัด Pattern เป็นองค์ประกอบที่ควบคุมผ่าน master ไม่ใช่สร้างใหม่ทุกเวอร์ชัน\n\nไม่ใช้ Mascot เพราะโครงการเน้น Artwork Governance และ Prepress ไม่ใช่การพัฒนาอัตลักษณ์ตัวละคร\n\nสร้าง master artwork และ SKU matrix เชื่อม revision, dieline, สีหมึก และขั้นตอนอนุมัติ แยกเลเยอร์ print, die-cut, white ink หรือ spot ตามข้อกำหนดงาน\n\nวางระบบ Master Artwork โดยแยกองค์ประกอบคงที่ออกจากองค์ประกอบที่เปลี่ยนได้ตาม SKU เช่น ชื่อรส ปริมาตร และข้อมูลที่เจ้าของผลิตภัณฑ์ตรวจรับรอง ลายผลไม้มีกรอบการวางและพื้นที่ปลอดภัยของตัวเองเพื่อไม่ให้รุกเข้าไปในข้อมูลสำคัญ ใช้ตาราง SKU ควบคู่กับชื่อไฟล์และ Revision ที่ตรวจย้อนกลับได้ ไม่เพิ่ม Mascot เพราะงานนี้เป็นการจัดระบบ Artwork ที่มีอยู่ ไม่ใช่การสร้าง Character Identity ใหม่","en":"Build a master with fixed elements and SKU-specific names, volumes and owner-approved copy. Give fruit graphics a defined safe zone; link file names and revisions to an SKU matrix. A new character identity is unnecessary."}},{"step":"05","heading":{"th":"จากแนวคิดสู่การผลิต","en":"Production Strategy"},"body":{"th":"ตรวจขนาดจริง bleed safe area ฟอนต์ ภาพ bitmap ความละเอียดตามงาน โหมดสีและโปรไฟล์ที่โรงงานระบุ ตรวจ overprint/knockout และหมึกขาวหรือสีพิเศษเมื่อมีการใช้งาน ส่ง proof ตามขั้นตอนอนุมัติ\n\nการล็อก template ช่วยลดความคลาดเคลื่อนแต่ต้องเปิดทางให้แก้เมื่อขนาดจริงหรือเครื่องเปลี่ยน ทุกการเปลี่ยนต้องมี revision และ proof ใหม่ตามความเหมาะสม\n\nเริ่มจากรับ dieline ขนาดจริงจากโรงพิมพ์และยืนยันวัสดุ วิธีพิมพ์ และข้อกำหนดไฟล์ กำหนด bleed และ safe area ตามสเปกงาน แยกเส้นตัด หมึกขาว หรือ spot color เฉพาะเมื่อเกี่ยวข้อง และตรวจฟอนต์กับความละเอียดของภาพตามสภาพผลิตจริง เก็บไฟล์ต้นฉบับที่แก้ไขได้แยกจากไฟล์ส่งผลิตที่ผ่านการอนุมัติ การเปลี่ยนขนาดฉลากต้องตรวจตำแหน่งใหม่ ไม่ใช่ Scale Artwork แบบอัตโนมัติโดยไม่ตรวจข้อมูล","en":"Obtain actual dielines and printer-specific bleed, safe-area, substrate and colour requirements. Separate vector cut paths and white/spot inks only as applicable; verify fonts and effective resolution, and keep editable masters separate from approved print PDFs."}},{"step":"06","heading":{"th":"การทดสอบและตรวจสอบ","en":"Quality Control"},"body":{"th":"ใช้ checklist ก่อนส่งงาน ตรวจข้อความกับต้นฉบับที่อนุมัติ เปรียบเทียบ PDF proof กับ master ตรวจบาร์โค้ดและข้อมูลสำคัญบนตัวอย่างจริง พร้อมบันทึกการอนุมัติแต่ละ Revision\n\nตรวจไฟล์ขนาดจริง bleed safe area ฟอนต์ ความละเอียดและสีตามสเปกโรงงาน ตรวจ overprint และ barcode จากตัวอย่างพิมพ์เมื่อเกี่ยวข้อง ไม่อ้างผลลดของเสียก่อนมีข้อมูลจริง\n\nจัดจุดตรวจเป็นสามช่วง: ตรวจเนื้อหาโดยเจ้าของสินค้า ตรวจ Prepress โดยฝ่ายเตรียมไฟล์ และตรวจ Proof ร่วมกับผู้ผลิต เปรียบเทียบเวอร์ชันก่อนและหลังแก้ไข ตรวจ overprint และการแยกสีตามงานจริง ตรวจบาร์โค้ดจากตัวอย่างพิมพ์หากมี บันทึกว่าใครอนุมัติ Revision ใดและเมื่อใด หากมีการแก้หลังอนุมัติ ให้เปิดรอบตรวจเฉพาะรายการที่ได้รับผลกระทบก่อนส่งผลิตใหม่","en":"Assign copy approval, preflight and proof responsibilities. Inspect revisions, separation, overprint, barcode samples where relevant and actual-size copy. Record the approved revision and reopen affected checks when artwork changes."}},{"step":"07","heading":{"th":"คุณค่าที่คาดหวัง","en":"Concept Outcome"},"body":{"th":"ต้นแบบแสดงแนวทางควบคุมความเสี่ยงก่อนผลิต และสร้างจุดตรวจที่ใช้ซ้ำได้กับหลาย SKU ไม่มีการอ้างอิงว่าลดเวลาหรือข้อผิดพลาดได้เป็นเปอร์เซ็นต์จริง\n\nระบบที่คาดหวังจะทำให้การส่งต่องานมีหลักอ้างอิงเดียวกันและตรวจสอบย้อนกลับได้เมื่อมีคำถามเกี่ยวกับไฟล์หรือสี ตัวชี้วัดที่เสนอสำหรับงานจริงคือจำนวนรอบแก้ก่อนผลิต ประเภทข้อผิดพลาดที่พบ และเวลาที่ใช้ตรวจรับไฟล์แต่ละ SKU โดยยังไม่อ้างว่าสามารถลดของเสียหรือเวลาลงได้เท่าใดจนกว่าจะมีข้อมูลเปรียบเทียบจากการใช้งานจริง","en":"The intended outcome is a traceable handoff with a shared reference for files and colours. Future evaluation can track correction rounds, error categories and review time per SKU; no measured waste or time reduction is asserted."}}],"storytelling":{"opening":"CITRUS เป็นโจทย์จำลองการเตรียมงานฉลากเครื่องดื่ม เมื่อมีรสชาติใหม่และขนาดขวดหลายแบบ งานที่ดูคล้ายกันอาจถูกส่งข้ามเวอร์ชันได้ง่าย จึงต้องคิดถึงคนที่รับไฟล์ต่อและวิธีอนุมัติตั้งแต่ต้น","pain_point":"ไฟล์ผิดขนาด ข้อมูลไม่ครบ หรือสีพิเศษไม่แยกจากกราฟิก อาจทำให้เกิดการแก้ไขซ้ำหรือผลิตผิด ความเสี่ยงเพิ่มขึ้นเมื่อมีหลาย SKU และผู้เกี่ยวข้องหลายฝ่าย","big_idea":"From Artwork to Print — ใช้ระบบการจัดการไฟล์ที่รักษาเจตนาการออกแบบและตรวจสอบย้อนกลับได้","logo_rationale":"คงตำแหน่ง wordmark และองค์ประกอบส้มเป็น master brand asset ไม่ออกแบบโลโก้ใหม่เพื่อความต่างโดยไม่จำเป็น ตรวจขนาดและสีตามสเปกที่อนุมัติ","pattern_rationale":"ใช้กราฟิกผลไม้เป็น secondary asset ที่มีกรอบและระยะปลอดภัยชัดเจน แยกจากข้อมูลสำคัญและเส้นตัด Pattern เป็นองค์ประกอบที่ควบคุมผ่าน master ไม่ใช่สร้างใหม่ทุกเวอร์ชัน","mascot_rationale":"ไม่ใช้ Mascot เพราะโครงการเน้น Artwork Governance และ Prepress ไม่ใช่การพัฒนาอัตลักษณ์ตัวละคร","application_system":"สร้าง master artwork และ SKU matrix เชื่อม revision, dieline, สีหมึก และขั้นตอนอนุมัติ แยกเลเยอร์ print, die-cut, white ink หรือ spot ตามข้อกำหนดงาน","trade_off":"การล็อก template ช่วยลดความคลาดเคลื่อนแต่ต้องเปิดทางให้แก้เมื่อขนาดจริงหรือเครื่องเปลี่ยน ทุกการเปลี่ยนต้องมี revision และ proof ใหม่ตามความเหมาะสม","validation_plan":"ตรวจไฟล์ขนาดจริง bleed safe area ฟอนต์ ความละเอียดและสีตามสเปกโรงงาน ตรวจ overprint และ barcode จากตัวอย่างพิมพ์เมื่อเกี่ยวข้อง ไม่อ้างผลลดของเสียก่อนมีข้อมูลจริง","visual_asset_brief":["Artwork master grid","SKU and revision matrix","Layer separation diagram","Preflight checklist visual","Proof comparison concept"]},"deliverables":["Artwork master concept","Prepress checklist","Proof & revision workflow","Production handoff specification"],"assetNotes":"โลโก้เวกเตอร์ต้นแบบสร้างแยกจากภาพจำลอง อาจมีรายละเอียดไม่ตรงกับโลโก้ใน Mockup ทุกจุด; ภาพ hero และ card มาจากภาพเดียวกัน ไม่ใช่ภาพถ่ายจริง; ชื่อแบรนด์ยังไม่ได้ตรวจสอบสิทธิ์เครื่องหมายการค้า","featured":false}];
const items=window.SCWORK_CONCEPT_PROJECTS;if(!Array.isArray(items)||items.length!==10)return;
for(const item of items){const d=deep.find(x=>x.brand===item.mockBrand.name);if(!d)continue;item.title.th=d.title;item.summary.th=d.summary;item.fit.th=d.summary;item.headline=d.headline;item.timeline=d.timeline;item.storytelling=d.storytelling;item.deliverables=d.deliverables;item.assetNotes=d.assetNotes;item.featured=d.featured;item.contentVersion="3.0";if(item.id==="ecolabel"){item.cover=item.hero=item.image=item.mockBrand.logo;item.cardDimensions=item.heroDimensions=[620,144];item.identityOnly=true;}}
// V2.1.73: card-only visuals; keep existing case hero and concept status.
for(const item of items){
 if(item.featured && item.heroDimensions[0]>=768){item.cover=item.image=item.hero;item.cardDimensions=[...item.heroDimensions];}
 if(item.id==="ecolabel"){item.cover=item.image="./assets/images/portfolio/concept-10/ecolabel/cover-study-v2173.svg";item.cardDimensions=[1200,750];}
 if(item.id==="citrus"){item.cover=item.image="./assets/images/knowledge/artwork-preflight.webp";item.cardDimensions=[1200,750];}
}
window.SCWORK_PORTFOLIO_ITEMS=items;
})();
